window.ENGLISH_B_QUESTIONS = [

  /* ===================== 词汇（vocabulary）· 55 题 ===================== */
  {"id":"voc-001","type":"vocabulary","kind":"single","score":1,"bank":"B级词汇","stem":"Please choose the word that best completes the sentence: “The manager asked his secretary to ______ the meeting at once.”","options":[{"key":"A","text":"attend"},{"key":"B","text":"pretend"},{"key":"C","text":"extend"},{"key":"D","text":"depend"}],"answer":"A","explanation":"attend the meeting 意为“出席会议”，符合句意“经理让秘书立即参加会议”。pretend 假装；extend 延长；depend 依赖。"},
  {"id":"voc-002","type":"vocabulary","kind":"single","score":1,"bank":"B级词汇","stem":"“He is ______ for the poor results of the project.”","options":[{"key":"A","text":"responsible"},{"key":"B","text":"possible"},{"key":"C","text":"reasonable"},{"key":"D","text":"available"}],"answer":"A","explanation":"be responsible for 意为“对……负责”，句意“他对项目糟糕的结果负责”。其余三项语义不符。"},
  {"id":"voc-003","type":"vocabulary","kind":"single","score":1,"bank":"B级词汇","stem":"The new bridge will greatly ______ the traffic problem in this area.","options":[{"key":"A","text":"relieve"},{"key":"B","text":"receive"},{"key":"C","text":"remove"},{"key":"D","text":"recover"}],"answer":"A","explanation":"relieve“缓解”，relieve the traffic problem 缓解交通问题。receive 收到；remove 移除；recover 恢复。"},
  {"id":"voc-004","type":"vocabulary","kind":"single","score":1,"bank":"B级词汇","stem":"Please ______ the goods carefully before you sign the receipt.","options":[{"key":"A","text":"check"},{"key":"B","text":"change"},{"key":"C","text":"choose"},{"key":"D","text":"charge"}],"answer":"A","explanation":"check“检查、核对”，check the goods 核对货物。句意“签收前请仔细核对货物”。"},
  {"id":"voc-005","type":"vocabulary","kind":"single","score":1,"bank":"B级词汇","stem":"“We need to ______ a plan for the new product before next month.”","options":[{"key":"A","text":"work out"},{"key":"B","text":"work on"},{"key":"C","text":"work in"},{"key":"D","text":"work at"}],"answer":"A","explanation":"work out a plan 制定计划。work on 从事；work in 渗入；work at 致力于。"},
  {"id":"voc-006","type":"vocabulary","kind":"single","score":1,"bank":"B级词汇","stem":"“Learning a foreign language ______ a lot of time and effort.”","options":[{"key":"A","text":"requires"},{"key":"B","text":"requests"},{"key":"C","text":"reports"},{"key":"D","text":"repeats"}],"answer":"A","explanation":"require 需要，require time and effort 需要时间和精力。request 请求；report 报告；repeat 重复。"},
  {"id":"voc-007","type":"vocabulary","kind":"single","score":1,"bank":"B级词汇","stem":"“The company will ______ ten new employees this year.”","options":[{"key":"A","text":"employ"},{"key":"B","text":"enjoy"},{"key":"C","text":"empty"},{"key":"D","text":"enable"}],"answer":"A","explanation":"employ 雇佣，employ ten new employees 雇佣十名新员工。其余三项语义不符。"},
  {"id":"voc-008","type":"vocabulary","kind":"single","score":1,"bank":"B级词汇","stem":"“You should ______ your mistakes and try to do better next time.”","options":[{"key":"A","text":"learn from"},{"key":"B","text":"learn about"},{"key":"C","text":"learn of"},{"key":"D","text":"learn by"}],"answer":"A","explanation":"learn from one's mistakes 从错误中学习。句意“你应该从错误中学习，下次做得更好”。"},
  {"id":"voc-009","type":"vocabulary","kind":"single","score":1,"bank":"B级词汇","stem":"The price of this computer is too high. Can you give me a ______?","options":[{"key":"A","text":"discount"},{"key":"B","text":"distance"},{"key":"C","text":"direction"},{"key":"D","text":"discovery"}],"answer":"A","explanation":"give a discount 打折。句意“这台电脑价格太高，能给我打个折吗？”"},
  {"id":"voc-010","type":"vocabulary","kind":"single","score":1,"bank":"B级词汇","stem":"“I'm ______ in the position of Sales Manager advertised on your website.”","options":[{"key":"A","text":"interested"},{"key":"B","text":"interesting"},{"key":"C","text":"interrupted"},{"key":"D","text":"international"}],"answer":"A","explanation":"be interested in 对……感兴趣。表示人的感受用 interested，有趣的用 interesting。"},
  {"id":"voc-101","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"The heavy rain seriously ______ the crops in the southern part of the country.","options":[{"key":"A","text":"affected"},{"key":"B","text":"effected"},{"key":"C","text":"afforded"},{"key":"D","text":"offered"}],"answer":"A","explanation":"affect 是动词，意为“影响”，affect the crops 影响庄稼。effect 作动词时意为“实现、使发生”，不表示影响；afford 负担得起；offer 提供。"},
  {"id":"voc-102","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"Everyone was invited to the party ______ Tom, who was ill in bed that day.","options":[{"key":"A","text":"accept"},{"key":"B","text":"except"},{"key":"C","text":"beside"},{"key":"D","text":"besides"}],"answer":"B","explanation":"except 意为“除……之外（不包括）”，符合“汤姆因病没被算在内”。accept 是动词“接受”，词性不符；beside 在……旁边；besides 除……之外还有（包括）。"},
  {"id":"voc-103","type":"vocabulary","kind":"single","score":1,"bank":"动词短语","stem":"The noise from the construction site was so loud that we could hardly ______ it.","options":[{"key":"A","text":"put off"},{"key":"B","text":"put on"},{"key":"C","text":"put up with"},{"key":"D","text":"put away"}],"answer":"C","explanation":"put up with 意为“忍受”，与句意“几乎忍受不了噪音”相符。put off 推迟；put on 穿上/上演；put away 把……收起来。"},
  {"id":"voc-104","type":"vocabulary","kind":"single","score":1,"bank":"动词短语","stem":"We have ______ paper and ink. Please order some more from the supplier.","options":[{"key":"A","text":"run into"},{"key":"B","text":"run over"},{"key":"C","text":"run after"},{"key":"D","text":"run out of"}],"answer":"D","explanation":"run out of 意为“用完、耗尽”，run out of paper and ink 用完纸张和墨水。run into 偶遇/撞上；run over 碾过；run after 追赶。"},
  {"id":"voc-105","type":"vocabulary","kind":"single","score":1,"bank":"动词短语","stem":"Mr. Wang retired last year, and a young engineer ______ his position in the company.","options":[{"key":"A","text":"took over"},{"key":"B","text":"took off"},{"key":"C","text":"took up"},{"key":"D","text":"took out"}],"answer":"A","explanation":"take over 意为“接管、接任”，take over his position 接替他的职位。take off 起飞/脱下；take up 开始从事/占用；take out 取出。"},
  {"id":"voc-106","type":"vocabulary","kind":"single","score":1,"bank":"动词短语","stem":"The company was ______ in 1998 and now has more than 2,000 employees.","options":[{"key":"A","text":"set off"},{"key":"B","text":"set up"},{"key":"C","text":"set out"},{"key":"D","text":"set aside"}],"answer":"B","explanation":"set up 意为“建立、创办”，与“公司于1998年成立”相符，此处为被动语态 be set up。set off 出发/引爆；set out 出发/着手；set aside 把……放在一边/留出。"},
  {"id":"voc-107","type":"vocabulary","kind":"single","score":1,"bank":"动词短语","stem":"The machine ______ suddenly and all the workers had to stop their work.","options":[{"key":"A","text":"broke out"},{"key":"B","text":"broke into"},{"key":"C","text":"broke down"},{"key":"D","text":"broke up"}],"answer":"C","explanation":"break down 意为“（机器）出故障、坏掉”。break out 爆发（战争、火灾）；break into 闯入；break up 分手/解散。"},
  {"id":"voc-108","type":"vocabulary","kind":"single","score":1,"bank":"动词短语","stem":"I happened to ______ my former English teacher in the bookstore yesterday.","options":[{"key":"A","text":"come up"},{"key":"B","text":"come over"},{"key":"C","text":"come about"},{"key":"D","text":"come across"}],"answer":"D","explanation":"come across 意为“偶然遇到、碰见”，与 happen to meet 意思一致。come up 出现/被提出；come over 顺便来访；come about 发生。"},
  {"id":"voc-109","type":"vocabulary","kind":"single","score":1,"bank":"固定搭配","stem":"You should ______ attention to your spelling when you write a business letter.","options":[{"key":"A","text":"pay"},{"key":"B","text":"take"},{"key":"C","text":"give"},{"key":"D","text":"make"}],"answer":"A","explanation":"pay attention to 是固定搭配，意为“注意、重视”。take/give/make 都不能与 attention to 构成该搭配。"},
  {"id":"voc-110","type":"vocabulary","kind":"single","score":1,"bank":"固定搭配","stem":"He has made up his ______ to study abroad after graduation.","options":[{"key":"A","text":"heart"},{"key":"B","text":"mind"},{"key":"C","text":"decision"},{"key":"D","text":"idea"}],"answer":"B","explanation":"make up one's mind 是固定短语，意为“下定决心”。虽然 make a decision 也可以，但 made up his 只与 mind 搭配。"},
  {"id":"voc-111","type":"vocabulary","kind":"single","score":1,"bank":"固定搭配","stem":"The young man is very good ______ repairing computers.","options":[{"key":"A","text":"for"},{"key":"B","text":"in"},{"key":"C","text":"at"},{"key":"D","text":"with"}],"answer":"C","explanation":"be good at 是固定搭配，意为“擅长于”，后接名词或动名词。"},
  {"id":"voc-112","type":"vocabulary","kind":"single","score":1,"bank":"固定搭配","stem":"It took the workers three days to ______ the new machine.","options":[{"key":"A","text":"put forward"},{"key":"B","text":"put down"},{"key":"C","text":"put through"},{"key":"D","text":"put together"}],"answer":"D","explanation":"put together 意为“组装、装配”，符合“组装新机器”。put forward 提出；put down 放下/写下；put through 接通电话。"},
  {"id":"voc-113","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"The manager asked the clerk to ______ the price of the new product.","options":[{"key":"A","text":"raise"},{"key":"B","text":"rise"},{"key":"C","text":"arise"},{"key":"D","text":"arouse"}],"answer":"A","explanation":"raise 是及物动词，意为“提高、举起”，后接宾语 the price。rise 是不及物动词“上升”；arise 不及物，意为“出现、产生”；arouse 意为“唤起（情感）”。"},
  {"id":"voc-114","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"The company ______ its customers a free gift for their support.","options":[{"key":"A","text":"afforded"},{"key":"B","text":"offered"},{"key":"C","text":"affected"},{"key":"D","text":"refused"}],"answer":"B","explanation":"offer sb. sth. 意为“向某人提供某物”，符合“公司向顾客赠送礼品”。afford 买得起；affect 影响；refuse 拒绝，语义不符。"},
  {"id":"voc-115","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"Please ______ me of the meeting time as soon as you get the notice.","options":[{"key":"A","text":"remember"},{"key":"B","text":"memorize"},{"key":"C","text":"remind"},{"key":"D","text":"mention"}],"answer":"C","explanation":"remind sb. of sth. 意为“提醒某人某事”，符合句意。remember 记得（不接 sb. of）；memorize 记住、背诵；mention 提及。"},
  {"id":"voc-116","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"The manager ______ that the report should be finished before Friday.","options":[{"key":"A","text":"stuck"},{"key":"B","text":"consisted"},{"key":"C","text":"resisted"},{"key":"D","text":"insisted"}],"answer":"D","explanation":"insist that... 意为“坚持要求”，其后从句常用 should + 动词原形。stick 坚持时须用 stick to；consist 与 of 连用；resist 抵抗。"},
  {"id":"voc-117","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"The secretary ______ the letter carefully before she typed it.","options":[{"key":"A","text":"revised"},{"key":"B","text":"reviewed"},{"key":"C","text":"reversed"},{"key":"D","text":"renewed"}],"answer":"A","explanation":"revise 意为“修改、修订（文稿）”，与 typed it 前后呼应。review 复习/评论；reverse 颠倒；renew 更新、续订。"},
  {"id":"voc-118","type":"vocabulary","kind":"single","score":1,"bank":"商务词汇","stem":"Customers who buy more than 100 pieces can get a 10% ______.","options":[{"key":"A","text":"account"},{"key":"B","text":"discount"},{"key":"C","text":"count"},{"key":"D","text":"discount card"}],"answer":"B","explanation":"discount 意为“折扣”，get a 10% discount 表示享受九折优惠。account 账户；count 计数；discount card 是“打折卡”，不能与百分数连用。"},
  {"id":"voc-119","type":"vocabulary","kind":"single","score":1,"bank":"商务词汇","stem":"The goods will be ______ to your address within five working days.","options":[{"key":"A","text":"developed"},{"key":"B","text":"decided"},{"key":"C","text":"delivered"},{"key":"D","text":"designed"}],"answer":"C","explanation":"deliver 意为“递送、送货”，deliver goods to an address 把货物送到某地址，此处用被动语态。develop 开发；decide 决定；design 设计。"},
  {"id":"voc-120","type":"vocabulary","kind":"single","score":1,"bank":"商务词汇","stem":"Mr. Smith is out of the office now. Would you like to leave a ______?","options":[{"key":"A","text":"note"},{"key":"B","text":"news"},{"key":"C","text":"information"},{"key":"D","text":"message"}],"answer":"D","explanation":"leave a message 是打电话时的固定说法，意为“留言”。note 便条；news 消息（不可数）；information 信息（不可数），均不与 leave a 搭配此义。"},
  {"id":"voc-121","type":"vocabulary","kind":"single","score":1,"bank":"商务词汇","stem":"Could you put me ______ to the Sales Department, please?","options":[{"key":"A","text":"through"},{"key":"B","text":"up"},{"key":"C","text":"off"},{"key":"D","text":"on"}],"answer":"A","explanation":"put sb. through to 是电话用语，意为“把某人的电话接到……”。put up 举起/搭建；put off 推迟；put on 穿上。"},
  {"id":"voc-122","type":"vocabulary","kind":"single","score":1,"bank":"求职词汇","stem":"Please send your ______, including your education and working experience, to our company.","options":[{"key":"A","text":"receive"},{"key":"B","text":"resume"},{"key":"C","text":"result"},{"key":"D","text":"record"}],"answer":"B","explanation":"resume 意为“简历”，与“包括教育和工作经历”相符。receive 收到；result 结果；record 记录。"},
  {"id":"voc-123","type":"vocabulary","kind":"single","score":1,"bank":"求职词汇","stem":"The new employees will receive a one-month ______ before they start to work.","options":[{"key":"A","text":"traffic"},{"key":"B","text":"travel"},{"key":"C","text":"training"},{"key":"D","text":"trouble"}],"answer":"C","explanation":"training 意为“培训”，a one-month training 为期一个月的培训，符合新员工上岗前的语境。"},
  {"id":"voc-124","type":"vocabulary","kind":"single","score":1,"bank":"求职词汇","stem":"If you are interested in this position, please ______ the application form online.","options":[{"key":"A","text":"fill up"},{"key":"B","text":"fill out of"},{"key":"C","text":"fill with"},{"key":"D","text":"fill in"}],"answer":"D","explanation":"fill in 意为“填写（表格）”，fill in the application form 填写申请表。fill up 装满；fill...with 用……装满，均不合此处。"},
  {"id":"voc-125","type":"vocabulary","kind":"single","score":1,"bank":"词性转换","stem":"The manager spoke to the workers in a very ______ voice.","options":[{"key":"A","text":"friendly"},{"key":"B","text":"friend"},{"key":"C","text":"friendliness"},{"key":"D","text":"friendship"}],"answer":"A","explanation":"此处需要形容词修饰 voice，friendly 虽以 -ly 结尾但是形容词，意为“友好的”。friend 和 friendship 是名词，friendliness 也是名词“友好”。"},
  {"id":"voc-126","type":"vocabulary","kind":"single","score":1,"bank":"词性转换","stem":"There has been a great ______ in the number of tourists this year.","options":[{"key":"A","text":"increasingly"},{"key":"B","text":"increase"},{"key":"C","text":"increasing"},{"key":"D","text":"increased"}],"answer":"B","explanation":"a great increase 中的 increase 是名词，意为“增长”，符合句意。increasingly 是副词；increasing 和 increased 是分词形式，不能与 a great 连用作主语。"},
  {"id":"voc-127","type":"vocabulary","kind":"single","score":1,"bank":"词性转换","stem":"The technician explained the ______ of the new machine to the workers.","options":[{"key":"A","text":"operate"},{"key":"B","text":"operating"},{"key":"C","text":"operation"},{"key":"D","text":"operational"}],"answer":"C","explanation":"the operation of the new machine 意为“新机器的操作方法”，此处需要名词，且 the...of 结构中间用名词。operate 是动词，operating 是分词/动名词，operational 是形容词。"},
  {"id":"voc-128","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"These two pictures are so ______ that I can hardly tell them apart.","options":[{"key":"A","text":"same"},{"key":"B","text":"likely"},{"key":"C","text":"equal"},{"key":"D","text":"similar"}],"answer":"D","explanation":"similar 意为“相似的”，be similar 作表语，符合“几乎分辨不出”。same 前必须加 the；likely 可能的（主语不能是物）；equal 相等的。"},
  {"id":"voc-129","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"I'd like to ______ this opportunity to thank you for your kind help.","options":[{"key":"A","text":"take advantage of"},{"key":"B","text":"take the place of"},{"key":"C","text":"take care of"},{"key":"D","text":"take part in"}],"answer":"A","explanation":"take advantage of 意为“利用（机会）”，take advantage of this opportunity 利用这次机会。take the place of 代替；take care of 照顾；take part in 参加（活动）。"},
  {"id":"voc-130","type":"vocabulary","kind":"single","score":1,"bank":"固定搭配","stem":"The new method is quite different ______ the old one.","options":[{"key":"A","text":"with"},{"key":"B","text":"from"},{"key":"C","text":"to"},{"key":"D","text":"of"}],"answer":"B","explanation":"be different from 是固定搭配，意为“与……不同”。"},
  {"id":"voc-131","type":"vocabulary","kind":"single","score":1,"bank":"固定搭配","stem":"The students are looking forward to ______ the famous writer next week.","options":[{"key":"A","text":"meet"},{"key":"B","text":"met"},{"key":"C","text":"meeting"},{"key":"D","text":"be met"}],"answer":"C","explanation":"look forward to 中的 to 是介词，后接名词或动名词，故用 meeting。"},
  {"id":"voc-132","type":"vocabulary","kind":"single","score":1,"bank":"固定搭配","stem":"It never ______ to me that he would refuse such a good offer.","options":[{"key":"A","text":"happened"},{"key":"B","text":"appeared"},{"key":"C","text":"took place"},{"key":"D","text":"occurred"}],"answer":"D","explanation":"It occurs to sb. that... 是固定句型，意为“某人想到……”。happen to sb. 意为“发生在某人身上”；appear 似乎；take place 发生（不与 to sb. 连用）。"},
  {"id":"voc-133","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"The plane is going to ______ in ten minutes. Please fasten your seat belt.","options":[{"key":"A","text":"take off"},{"key":"B","text":"take up"},{"key":"C","text":"take away"},{"key":"D","text":"take down"}],"answer":"A","explanation":"take off 意为“（飞机）起飞”，与“请系好安全带”的语境相符。take up 占用；take away 拿走；take down 记下/拆下。"},
  {"id":"voc-134","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"She was ______ to tears when she heard the good news.","options":[{"key":"A","text":"moving"},{"key":"B","text":"moved"},{"key":"C","text":"removed"},{"key":"D","text":"movable"}],"answer":"B","explanation":"be moved to tears 意为“感动得流泪”，moved 表示人“被感动的”。moving 意为“令人感动的”，用于修饰物；removed 移除的；movable 可移动的。"},
  {"id":"voc-135","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"The manager is very ______ with the progress the team has made.","options":[{"key":"A","text":"pleasant"},{"key":"B","text":"pleasing"},{"key":"C","text":"pleased"},{"key":"D","text":"pleasure"}],"answer":"C","explanation":"be pleased with 意为“对……感到满意”，主语是人。pleasant/pleasing 意为“令人愉快的”，修饰事物；pleasure 是名词。"},
  {"id":"voc-136","type":"vocabulary","kind":"single","score":1,"bank":"商务词汇","stem":"The goods you ordered are not ______ at the moment. We will send them next week.","options":[{"key":"A","text":"possible"},{"key":"B","text":"probable"},{"key":"C","text":"capable"},{"key":"D","text":"available"}],"answer":"D","explanation":"available 意为“可获得的、有现货的”，be available 表示“有货”。possible/probable 意为“可能的”；capable 与 of 连用，意为“能够”。"},
  {"id":"voc-137","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"We must ______ the meeting because the manager is on a business trip.","options":[{"key":"A","text":"postpone"},{"key":"B","text":"propose"},{"key":"C","text":"promote"},{"key":"D","text":"produce"}],"answer":"A","explanation":"postpone 意为“推迟、延期”，与“经理出差”的语境相符。propose 提议；promote 晋升/促进；produce 生产。"},
  {"id":"voc-138","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"The two companies have ______ an agreement on the new project.","options":[{"key":"A","text":"arrived"},{"key":"B","text":"reached"},{"key":"C","text":"got"},{"key":"D","text":"come"}],"answer":"B","explanation":"reach an agreement 是固定搭配，意为“达成协议”。arrive 须与 at 连用；get 不能直接接 agreement 表示达成；come 须与 to 连用。"},
  {"id":"voc-139","type":"vocabulary","kind":"single","score":1,"bank":"固定搭配","stem":"The doctor advised him to give up ______ because of his heart trouble.","options":[{"key":"A","text":"smoke"},{"key":"B","text":"to smoke"},{"key":"C","text":"smoking"},{"key":"D","text":"smoked"}],"answer":"C","explanation":"give up 后接名词或动名词，故用 smoking，表示“戒烟”。"},
  {"id":"voc-140","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"The old man ______ his glasses and began to read the newspaper.","options":[{"key":"A","text":"put off"},{"key":"B","text":"put out"},{"key":"C","text":"put up"},{"key":"D","text":"put on"}],"answer":"D","explanation":"put on 意为“戴上（眼镜）”，符合句意。put off 推迟；put out 熄灭；put up 举起/张贴/搭建。"},
  {"id":"voc-141","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"Mr. Li is a ______ engineer; he has worked in this field for over twenty years.","options":[{"key":"A","text":"experienced"},{"key":"B","text":"experiencing"},{"key":"C","text":"experience"},{"key":"D","text":"experiment"}],"answer":"A","explanation":"experienced 是形容词，意为“有经验的”，修饰 engineer。experiencing 是分词；experience 作名词或动词；experiment 是名词/动词“实验”。"},
  {"id":"voc-142","type":"vocabulary","kind":"single","score":1,"bank":"商务词汇","stem":"The meeting room is on the fifth floor. You can take the ______ to get there.","options":[{"key":"A","text":"escalator"},{"key":"B","text":"elevator"},{"key":"C","text":"entrance"},{"key":"D","text":"exit"}],"answer":"B","explanation":"elevator 意为“电梯（升降梯）”，在楼层间垂直运行。escalator 是自动扶梯；entrance 入口；exit 出口。"},
  {"id":"voc-143","type":"vocabulary","kind":"single","score":1,"bank":"固定搭配","stem":"You should ______ use of every chance to practise your spoken English.","options":[{"key":"A","text":"take"},{"key":"B","text":"do"},{"key":"C","text":"make"},{"key":"D","text":"get"}],"answer":"C","explanation":"make use of 是固定短语，意为“利用”，符合句意“你应当利用每一个机会练习英语口语”。"},
  {"id":"voc-144","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"The price of the house has ______ by 20% since last year.","options":[{"key":"A","text":"raised"},{"key":"B","text":"arisen"},{"key":"C","text":"rose"},{"key":"D","text":"risen"}],"answer":"D","explanation":"rise 是不及物动词，意为“上升、上涨”，此处用于现在完成时 have risen。raise 是及物动词，后面必须接宾语；arise 意为“产生”；rose 是 rise 的过去式，不能与 has 连用。"},
  {"id":"voc-145","type":"vocabulary","kind":"single","score":1,"bank":"词义辨析","stem":"He didn't ______ the job offer because the salary was too low.","options":[{"key":"A","text":"accept"},{"key":"B","text":"receive"},{"key":"C","text":"expect"},{"key":"D","text":"hope"}],"answer":"A","explanation":"accept 意为“（主观上）接受”，与 because 引导的原因从句相呼应。receive 意为“（客观上）收到”，不能说明是否接受；expect/hope 意为“期望/希望”，语义不符。"},

  /* ===================== 语法（grammar）· 55 题 ===================== */
  {"id":"gra-001","type":"grammar","kind":"single","score":1,"bank":"时态","stem":"“The children ______ games when their mother came home.”","options":[{"key":"A","text":"are playing"},{"key":"B","text":"were playing"},{"key":"C","text":"have played"},{"key":"D","text":"will play"}],"answer":"B","explanation":"when 引导的过去时间状语，主句表示“妈妈到家时孩子们正在做游戏”，用过去进行时 were playing。"},
  {"id":"gra-002","type":"grammar","kind":"single","score":1,"bank":"时态","stem":"“By the end of last year, we ______ more than 200 English words.”","options":[{"key":"A","text":"learned"},{"key":"B","text":"have learned"},{"key":"C","text":"had learned"},{"key":"D","text":"were learning"}],"answer":"C","explanation":"by the end of last year 表示“到去年年底为止”，用过去完成时 had learned。"},
  {"id":"gra-003","type":"grammar","kind":"single","score":1,"bank":"时态","stem":"“Look! Here ______ the bus. Let's hurry up.”","options":[{"key":"A","text":"come"},{"key":"B","text":"comes"},{"key":"C","text":"came"},{"key":"D","text":"is coming"}],"answer":"B","explanation":"Here 置于句首引导完全倒装，主语 the bus 为第三人称单数，用一般现在时 comes。"},
  {"id":"gra-004","type":"grammar","kind":"single","score":1,"bank":"非谓语","stem":"“______ the meeting, he left the room without saying a word.”","options":[{"key":"A","text":"Finish"},{"key":"B","text":"Finishing"},{"key":"C","text":"Having finished"},{"key":"D","text":"To finish"}],"answer":"C","explanation":"“结束会议”发生在“离开房间”之前，用分词的完成式 Having finished 作时间状语。"},
  {"id":"gra-005","type":"grammar","kind":"single","score":1,"bank":"非谓语","stem":"“The teacher told the students ______ in the classroom.”","options":[{"key":"A","text":"not to smoke"},{"key":"B","text":"not smoking"},{"key":"C","text":"don't smoke"},{"key":"D","text":"no smoking"}],"answer":"A","explanation":"tell sb. not to do sth. 告诉某人不要做某事，不定式否定式 not to smoke。"},
  {"id":"gra-006","type":"grammar","kind":"single","score":1,"bank":"从句","stem":"“Do you know ______ the meeting will begin?”","options":[{"key":"A","text":"when"},{"key":"B","text":"what"},{"key":"C","text":"who"},{"key":"D","text":"which"}],"answer":"A","explanation":"宾语从句询问时间，用 when 引导，意为“你知道会议什么时候开始吗？”"},
  {"id":"gra-007","type":"grammar","kind":"single","score":1,"bank":"从句","stem":"“This is the factory ______ my father worked ten years ago.”","options":[{"key":"A","text":"where"},{"key":"B","text":"which"},{"key":"C","text":"that"},{"key":"D","text":"what"}],"answer":"A","explanation":"先行词 factory 在定语从句中作地点状语，用关系副词 where，相当于 in which。"},
  {"id":"gra-008","type":"grammar","kind":"single","score":1,"bank":"虚拟语气","stem":"“If I ______ you, I would accept the offer.”","options":[{"key":"A","text":"am"},{"key":"B","text":"was"},{"key":"C","text":"were"},{"key":"D","text":"be"}],"answer":"C","explanation":"与现在事实相反的虚拟条件句，be 动词一律用 were，即 If I were you（如果我是你）。"},
  {"id":"gra-009","type":"grammar","kind":"single","score":1,"bank":"情态动词","stem":"“The light is still on. He ______ in the office.”","options":[{"key":"A","text":"must be"},{"key":"B","text":"can't be"},{"key":"C","text":"should be"},{"key":"D","text":"might not be"}],"answer":"A","explanation":"灯还亮着，据此推断“他一定在办公室”，用 must be 表示肯定的推测。"},
  {"id":"gra-010","type":"grammar","kind":"single","score":1,"bank":"比较级","stem":"“This problem is ______ than that one.”","options":[{"key":"A","text":"much difficult"},{"key":"B","text":"more difficult"},{"key":"C","text":"most difficult"},{"key":"D","text":"difficult"}],"answer":"B","explanation":"由 than 可知用比较级，difficult 为多音节词，用 more difficult。"},
  {"id":"gra-101","type":"grammar","kind":"single","score":1,"bank":"时态","stem":"Mr. Green ______ to China in 2008 and has lived in Beijing ever since.","options":[{"key":"A","text":"comes"},{"key":"B","text":"came"},{"key":"C","text":"has come"},{"key":"D","text":"had come"}],"answer":"B","explanation":"句中有明确的过去时间状语 in 2008，应用一般过去时 came。has come 不能与具体的过去时间连用；comes 与时间不符；had come 表示“过去的过去”，缺少过去参照点。"},
  {"id":"gra-102","type":"grammar","kind":"single","score":1,"bank":"时态","stem":"Look! The children ______ football on the playground.","options":[{"key":"A","text":"play"},{"key":"B","text":"played"},{"key":"C","text":"are playing"},{"key":"D","text":"have played"}],"answer":"C","explanation":"Look! 提示此刻正在发生的动作，用现在进行时 are playing。"},
  {"id":"gra-103","type":"grammar","kind":"single","score":1,"bank":"时态","stem":"We ______ each other since we graduated from the college.","options":[{"key":"A","text":"knew"},{"key":"B","text":"know"},{"key":"C","text":"had known"},{"key":"D","text":"have known"}],"answer":"D","explanation":"since 引导的从句用一般过去时，主句应用现在完成时，表示从过去持续到现在的状态，故用 have known。know 是状态动词，不用进行时。"},
  {"id":"gra-104","type":"grammar","kind":"single","score":1,"bank":"时态","stem":"By the end of last term, we ______ more than 2,000 English words.","options":[{"key":"A","text":"had learned"},{"key":"B","text":"have learned"},{"key":"C","text":"learned"},{"key":"D","text":"learn"}],"answer":"A","explanation":"by the end of last term 是过去完成时的标志，表示“到过去某一时间为止已经完成”，故用 had learned。"},
  {"id":"gra-105","type":"grammar","kind":"single","score":1,"bank":"时态","stem":"I ______ for the bus for half an hour, but it still hasn't come.","options":[{"key":"A","text":"have waited"},{"key":"B","text":"have been waiting"},{"key":"C","text":"waited"},{"key":"D","text":"am waiting"}],"answer":"B","explanation":"for half an hour 表示动作从过去持续到现在并将继续，用现在完成进行时 have been waiting 最贴切。"},
  {"id":"gra-106","type":"grammar","kind":"single","score":1,"bank":"时态","stem":"If it ______ tomorrow, we will stay at home.","options":[{"key":"A","text":"will rain"},{"key":"B","text":"rained"},{"key":"C","text":"rains"},{"key":"D","text":"is raining"}],"answer":"C","explanation":"条件状语从句中，主句用一般将来时，从句用一般现在时表将来，即“主将从现”，故用 rains。"},
  {"id":"gra-107","type":"grammar","kind":"single","score":1,"bank":"时态","stem":"He said that he ______ the report the next day.","options":[{"key":"A","text":"will finish"},{"key":"B","text":"finishes"},{"key":"C","text":"has finished"},{"key":"D","text":"would finish"}],"answer":"D","explanation":"主句是一般过去时，宾语从句须用相应的过去时态；the next day 表将来，故用过去将来时 would finish。"},
  {"id":"gra-108","type":"grammar","kind":"single","score":1,"bank":"被动语态","stem":"The new library ______ by the mayor last month.","options":[{"key":"A","text":"was opened"},{"key":"B","text":"opened"},{"key":"C","text":"is opened"},{"key":"D","text":"has been opened"}],"answer":"A","explanation":"主语 library 是动作的承受者，且时间为 last month，故用一般过去时的被动语态 was opened。"},
  {"id":"gra-109","type":"grammar","kind":"single","score":1,"bank":"被动语态","stem":"A lot of trees ______ in our city every spring.","options":[{"key":"A","text":"plant"},{"key":"B","text":"are planted"},{"key":"C","text":"planted"},{"key":"D","text":"have planted"}],"answer":"B","explanation":"trees 与 plant 是被动关系，且 every spring 表经常性动作，故用一般现在时的被动语态 are planted。"},
  {"id":"gra-110","type":"grammar","kind":"single","score":1,"bank":"被动语态","stem":"The problem ______ at the meeting now, so we have to wait.","options":[{"key":"A","text":"is discussing"},{"key":"B","text":"discusses"},{"key":"C","text":"is being discussed"},{"key":"D","text":"has discussed"}],"answer":"C","explanation":"now 表示正在进行，problem 与 discuss 是被动关系，故用现在进行时的被动语态 is being discussed。"},
  {"id":"gra-111","type":"grammar","kind":"single","score":1,"bank":"被动语态","stem":"English ______ in more than seventy countries in the world.","options":[{"key":"A","text":"speaks"},{"key":"B","text":"is speaking"},{"key":"C","text":"has spoken"},{"key":"D","text":"is spoken"}],"answer":"D","explanation":"English 是被说的语言，须用被动语态；表示客观事实用一般现在时，故用 is spoken。"},
  {"id":"gra-112","type":"grammar","kind":"single","score":1,"bank":"非谓语","stem":"I'm very sorry ______ you waiting for so long.","options":[{"key":"A","text":"to keep"},{"key":"B","text":"keeping"},{"key":"C","text":"kept"},{"key":"D","text":"keep"}],"answer":"A","explanation":"be sorry to do sth. 表示“抱歉做某事”，此处指“让你等了这么久，很抱歉”，故用不定式 to keep。"},
  {"id":"gra-113","type":"grammar","kind":"single","score":1,"bank":"非谓语","stem":"He is used to ______ up early in the morning.","options":[{"key":"A","text":"get"},{"key":"B","text":"getting"},{"key":"C","text":"got"},{"key":"D","text":"be got"}],"answer":"B","explanation":"be used to 中的 to 是介词，后接动名词，意为“习惯于做某事”，故用 getting。注意 used to do 才表示“过去常常”。"},
  {"id":"gra-114","type":"grammar","kind":"single","score":1,"bank":"非谓语","stem":"The film was so ______ that all of us burst into tears.","options":[{"key":"A","text":"moved"},{"key":"B","text":"move"},{"key":"C","text":"moving"},{"key":"D","text":"to move"}],"answer":"C","explanation":"修饰物 the film 应用现在分词转化的形容词 moving，意为“令人感动的”。moved 意为“（人）被感动的”。"},
  {"id":"gra-115","type":"grammar","kind":"single","score":1,"bank":"非谓语","stem":"______ from the top of the hill, the city looks like a big garden.","options":[{"key":"A","text":"Seeing"},{"key":"B","text":"To see"},{"key":"C","text":"See"},{"key":"D","text":"Seen"}],"answer":"D","explanation":"the city 与 see 是被动关系，即“城市被看”，故用过去分词 Seen 作状语。Seeing 表示主动，逻辑主语应是人。"},
  {"id":"gra-116","type":"grammar","kind":"single","score":1,"bank":"非谓语","stem":"It's no use ______ over spilt milk.","options":[{"key":"A","text":"crying"},{"key":"B","text":"to cry"},{"key":"C","text":"cry"},{"key":"D","text":"cried"}],"answer":"A","explanation":"It's no use doing sth. 是固定句型，意为“做某事没有用”，故用动名词 crying。"},
  {"id":"gra-117","type":"grammar","kind":"single","score":1,"bank":"非谓语","stem":"The manager had the letter ______ before he left the office.","options":[{"key":"A","text":"type"},{"key":"B","text":"typed"},{"key":"C","text":"to type"},{"key":"D","text":"typing"}],"answer":"B","explanation":"have sth. done 表示“让某事被做”，letter 与 type 是被动关系，故用过去分词 typed。"},
  {"id":"gra-118","type":"grammar","kind":"single","score":1,"bank":"从句","stem":"The man ______ is talking with our manager is from Canada.","options":[{"key":"A","text":"whom"},{"key":"B","text":"which"},{"key":"C","text":"who"},{"key":"D","text":"whose"}],"answer":"C","explanation":"先行词 the man 指人，且在定语从句中作主语，故用关系代词 who。whom 作宾语；which 指物；whose 表所属。"},
  {"id":"gra-119","type":"grammar","kind":"single","score":1,"bank":"从句","stem":"This is the hotel ______ we stayed during our holiday.","options":[{"key":"A","text":"which"},{"key":"B","text":"that"},{"key":"C","text":"who"},{"key":"D","text":"where"}],"answer":"D","explanation":"先行词 the hotel 是地点，且从句 we stayed 结构完整，缺少地点状语，故用关系副词 where（= in which）。"},
  {"id":"gra-120","type":"grammar","kind":"single","score":1,"bank":"从句","stem":"I still remember the day ______ we first met in the school library.","options":[{"key":"A","text":"when"},{"key":"B","text":"which"},{"key":"C","text":"where"},{"key":"D","text":"what"}],"answer":"A","explanation":"先行词 the day 是时间，从句中缺少时间状语，故用关系副词 when（= on which）。"},
  {"id":"gra-121","type":"grammar","kind":"single","score":1,"bank":"从句","stem":"I don't know ______ he will come to the meeting or not.","options":[{"key":"A","text":"if"},{"key":"B","text":"whether"},{"key":"C","text":"that"},{"key":"D","text":"what"}],"answer":"B","explanation":"与 or not 直接连用时只能用 whether，不能用 if。that 不表疑问；what 不能引导该结构。"},
  {"id":"gra-122","type":"grammar","kind":"single","score":1,"bank":"从句","stem":"______ he said at the meeting surprised all of us.","options":[{"key":"A","text":"That"},{"key":"B","text":"Which"},{"key":"C","text":"What"},{"key":"D","text":"It"}],"answer":"C","explanation":"主语从句中 said 缺少宾语，须用连接代词 What（= the thing that）。That 引导主语从句时不作成分；Which 表“哪一个”；It 不能引导从句。"},
  {"id":"gra-123","type":"grammar","kind":"single","score":1,"bank":"从句","stem":"We will not start the meeting ______ everyone arrives.","options":[{"key":"A","text":"while"},{"key":"B","text":"since"},{"key":"C","text":"because"},{"key":"D","text":"until"}],"answer":"D","explanation":"not...until... 意为“直到……才……”，符合句意“直到所有人都到了我们才开始开会”。"},
  {"id":"gra-124","type":"grammar","kind":"single","score":1,"bank":"从句","stem":"______ it was raining heavily, they went on with their work.","options":[{"key":"A","text":"Although"},{"key":"B","text":"Because"},{"key":"C","text":"So"},{"key":"D","text":"If"}],"answer":"A","explanation":"前后为让步关系“尽管雨下得很大，他们仍继续工作”，故用 Although。Because 表原因；So 是并列连词；If 表条件。"},
  {"id":"gra-125","type":"grammar","kind":"single","score":1,"bank":"从句","stem":"The reason ______ he was late was that he missed the early bus.","options":[{"key":"A","text":"which"},{"key":"B","text":"why"},{"key":"C","text":"when"},{"key":"D","text":"what"}],"answer":"B","explanation":"先行词是 the reason，从句中缺少原因状语，故用关系副词 why（= for which）。"},
  {"id":"gra-126","type":"grammar","kind":"single","score":1,"bank":"虚拟语气","stem":"If I ______ you, I would accept the offer.","options":[{"key":"A","text":"am"},{"key":"B","text":"was"},{"key":"C","text":"were"},{"key":"D","text":"will be"}],"answer":"C","explanation":"与现在事实相反的虚拟条件句，从句用 if + 主语 + were（或动词过去式），主句用 would + 动词原形。在 if I were you 中固定用 were。"},
  {"id":"gra-127","type":"grammar","kind":"single","score":1,"bank":"虚拟语气","stem":"The doctor suggested that the patient ______ in bed for a few days.","options":[{"key":"A","text":"stays"},{"key":"B","text":"stayed"},{"key":"C","text":"is staying"},{"key":"D","text":"stay"}],"answer":"D","explanation":"suggest 表示“建议”时，其后的宾语从句用虚拟语气，谓语为 (should) + 动词原形，故用 stay。"},
  {"id":"gra-128","type":"grammar","kind":"single","score":1,"bank":"虚拟语气","stem":"If he ______ harder last term, he would have passed the exam.","options":[{"key":"A","text":"had worked"},{"key":"B","text":"worked"},{"key":"C","text":"works"},{"key":"D","text":"would work"}],"answer":"A","explanation":"与过去事实相反的虚拟条件句：从句用 had + 过去分词，主句用 would have + 过去分词。句中 last term 表明与过去事实相反。"},
  {"id":"gra-129","type":"grammar","kind":"single","score":1,"bank":"虚拟语气","stem":"It is necessary that every student ______ the safety rules.","options":[{"key":"A","text":"follows"},{"key":"B","text":"follow"},{"key":"C","text":"followed"},{"key":"D","text":"will follow"}],"answer":"B","explanation":"It is necessary/important that... 句型中，主语从句用虚拟语气，谓语为 (should) + 动词原形，故用 follow。"},
  {"id":"gra-130","type":"grammar","kind":"single","score":1,"bank":"情态动词","stem":"You ______ hand in your homework on time. It's a rule of our class.","options":[{"key":"A","text":"can"},{"key":"B","text":"may"},{"key":"C","text":"must"},{"key":"D","text":"need"}],"answer":"C","explanation":"must 表示“必须”，符合“这是班规”的强制性语境。can 能够；may 可以；need 需要，均不表示规定要求的必须。"},
  {"id":"gra-131","type":"grammar","kind":"single","score":1,"bank":"情态动词","stem":"It's already ten o'clock. The manager ______ be in his office now.","options":[{"key":"A","text":"can"},{"key":"B","text":"need"},{"key":"C","text":"would"},{"key":"D","text":"must"}],"answer":"D","explanation":"must be 表示肯定的推测，意为“一定在”。can 用于推测时通常用于疑问句或否定句；need 需要；would 表意愿或过去将来。"},
  {"id":"gra-132","type":"grammar","kind":"single","score":1,"bank":"情态动词","stem":"You ______ have told her the truth earlier. Now she is very angry.","options":[{"key":"A","text":"should"},{"key":"B","text":"must"},{"key":"C","text":"can"},{"key":"D","text":"need"}],"answer":"A","explanation":"should have done 表示“本该做而没做”，含责备语气，符合“现在她很生气”的语境。must have done 表示对过去的肯定推测；can 不用于此结构；needn't have done 表示“本不必做”。"},
  {"id":"gra-133","type":"grammar","kind":"single","score":1,"bank":"情态动词","stem":"______ I use your dictionary for a moment?","options":[{"key":"A","text":"Must"},{"key":"B","text":"May"},{"key":"C","text":"Need"},{"key":"D","text":"Should"}],"answer":"B","explanation":"May I...? 用于礼貌地请求许可，符合借用词典的语境。Must 必须；Need 需要；Should 应该。"},
  {"id":"gra-134","type":"grammar","kind":"single","score":1,"bank":"情态动词","stem":"You ______ have hurried. The train was delayed for two hours.","options":[{"key":"A","text":"mustn't"},{"key":"B","text":"shouldn't"},{"key":"C","text":"needn't"},{"key":"D","text":"couldn't"}],"answer":"C","explanation":"needn't have done 表示“本来不必做（却做了）”，与“火车晚点两小时”相符。mustn't 表禁止；shouldn't have done 表责备“本不该做”；couldn't have done 表对过去的否定推测。"},
  {"id":"gra-135","type":"grammar","kind":"single","score":1,"bank":"比较级","stem":"This is ______ film I have ever seen.","options":[{"key":"A","text":"most interesting"},{"key":"B","text":"more interesting"},{"key":"C","text":"the more interesting"},{"key":"D","text":"the most interesting"}],"answer":"D","explanation":"I have ever seen 表明在范围内比较，须用最高级，且形容词最高级前要加 the，故用 the most interesting。"},
  {"id":"gra-136","type":"grammar","kind":"single","score":1,"bank":"比较级","stem":"The ______ you work, the more progress you will make.","options":[{"key":"A","text":"harder"},{"key":"B","text":"hard"},{"key":"C","text":"hardest"},{"key":"D","text":"more hard"}],"answer":"A","explanation":"“the + 比较级..., the + 比较级...” 表示“越……越……”，故用 harder。hard 的比较级是 harder，不是 more hard。"},
  {"id":"gra-137","type":"grammar","kind":"single","score":1,"bank":"比较级","stem":"Her spoken English is much ______ than mine.","options":[{"key":"A","text":"good"},{"key":"B","text":"better"},{"key":"C","text":"well"},{"key":"D","text":"best"}],"answer":"B","explanation":"than 表明用比较级，good 的比较级是 better；much 可修饰比较级表示程度。"},
  {"id":"gra-138","type":"grammar","kind":"single","score":1,"bank":"比较级","stem":"The population of Shanghai is larger than ______ of Nanjing.","options":[{"key":"A","text":"this"},{"key":"B","text":"it"},{"key":"C","text":"that"},{"key":"D","text":"those"}],"answer":"C","explanation":"比较的对象是两地的人口，用 that 代替前面提到的不可数名词 the population，避免重复。those 代替复数名词。"},
  {"id":"gra-139","type":"grammar","kind":"single","score":1,"bank":"主谓一致","stem":"Neither the students nor the teacher ______ interested in the film.","options":[{"key":"A","text":"are"},{"key":"B","text":"were"},{"key":"C","text":"be"},{"key":"D","text":"is"}],"answer":"D","explanation":"neither...nor... 连接两个主语时，谓语遵循“就近原则”，靠近谓语的 the teacher 是单数，故用 is。"},
  {"id":"gra-140","type":"grammar","kind":"single","score":1,"bank":"主谓一致","stem":"The number of students in our school ______ increasing year by year.","options":[{"key":"A","text":"is"},{"key":"B","text":"are"},{"key":"C","text":"have"},{"key":"D","text":"were"}],"answer":"A","explanation":"the number of... 意为“……的数量”，谓语用单数 is。a number of... 意为“许多”，谓语才用复数。"},
  {"id":"gra-141","type":"grammar","kind":"single","score":1,"bank":"主谓一致","stem":"Either you or I ______ going to attend the meeting tomorrow.","options":[{"key":"A","text":"is"},{"key":"B","text":"am"},{"key":"C","text":"are"},{"key":"D","text":"be"}],"answer":"B","explanation":"either...or... 连接主语时谓语遵循“就近原则”，靠近谓语的 I 应搭配 am。"},
  {"id":"gra-142","type":"grammar","kind":"single","score":1,"bank":"冠词","stem":"He is ______ honest man and everyone in the village trusts him.","options":[{"key":"A","text":"a"},{"key":"B","text":"the"},{"key":"C","text":"an"},{"key":"D","text":"不填"}],"answer":"C","explanation":"honest 的首字母 h 不发音，单词以元音音素开头，故用不定冠词 an 表示“一个诚实的人”。"},
  {"id":"gra-143","type":"grammar","kind":"single","score":1,"bank":"冠词","stem":"______ Yellow River is the second longest river in China.","options":[{"key":"A","text":"A"},{"key":"B","text":"An"},{"key":"C","text":"不填"},{"key":"D","text":"The"}],"answer":"D","explanation":"江河、海洋、山脉等专有名词前须加定冠词 the，故用 The Yellow River。"},
  {"id":"gra-144","type":"grammar","kind":"single","score":1,"bank":"介词","stem":"The meeting will begin ______ nine o'clock ______ the morning of May 1st.","options":[{"key":"A","text":"at; on"},{"key":"B","text":"on; in"},{"key":"C","text":"in; at"},{"key":"D","text":"at; in"}],"answer":"A","explanation":"具体时刻前用 at（at nine o'clock）；具体某一天的早上用 on（on the morning of May 1st）。"},
  {"id":"gra-145","type":"grammar","kind":"single","score":1,"bank":"倒装句","stem":"Not until he failed the exam ______ the importance of hard work.","options":[{"key":"A","text":"he realized"},{"key":"B","text":"did he realize"},{"key":"C","text":"he did realize"},{"key":"D","text":"realized he"}],"answer":"B","explanation":"Not until 置于句首时，主句须用部分倒装，即把助动词提到主语前，故用 did he realize。"},

  /* ===================== 阅读理解（reading）· 36 题 ===================== */
  {"id":"read-001","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Notice\n\nThe school library will be closed from July 20 to August 10 for repairs. All borrowed books due during this period should be returned by July 18. You may also renew your books online before July 18. We are sorry for the inconvenience.","stem":"How long will the library be closed?","options":[{"key":"A","text":"About two weeks."},{"key":"B","text":"About three weeks."},{"key":"C","text":"About one month."},{"key":"D","text":"About two months."}],"answer":"B","explanation":"图书馆从 7 月 20 日到 8 月 10 日关闭，约三周（20 天）。"},
  {"id":"read-002","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Notice\n\nThe school library will be closed from July 20 to August 10 for repairs. All borrowed books due during this period should be returned by July 18. You may also renew your books online before July 18. We are sorry for the inconvenience.","stem":"When should the due books be returned?","options":[{"key":"A","text":"By July 18."},{"key":"B","text":"By July 20."},{"key":"C","text":"By August 10."},{"key":"D","text":"Before August 10."}],"answer":"A","explanation":"通知明确写“All borrowed books due during this period should be returned by July 18”，应于 7 月 18 日前归还。"},
  {"id":"read-003","type":"reading","kind":"passage","score":2,"bank":"科普说明","passage":"Water covers about 70% of the Earth's surface, but most of it is salt water that people cannot drink. Only about 3% of the world's water is fresh water, and most of that is frozen in ice caps. As a result, saving water is very important for everyone.","stem":"What percentage of the world's water is fresh water?","options":[{"key":"A","text":"About 70%."},{"key":"B","text":"About 30%."},{"key":"C","text":"About 3%."},{"key":"D","text":"About 13%."}],"answer":"C","explanation":"文中“Only about 3% of the world's water is fresh water”，淡水约占 3%。"},
  {"id":"read-004","type":"reading","kind":"passage","score":2,"bank":"科普说明","passage":"Water covers about 70% of the Earth's surface, but most of it is salt water that people cannot drink. Only about 3% of the world's water is fresh water, and most of that is frozen in ice caps. As a result, saving water is very important for everyone.","stem":"Why is saving water important?","options":[{"key":"A","text":"Because water is very expensive."},{"key":"B","text":"Because most fresh water is not available for use."},{"key":"C","text":"Because the Earth is getting warmer."},{"key":"D","text":"Because there is no salt water."}],"answer":"B","explanation":"大部分淡水冻结在冰盖中无法直接使用，所以节约用水很重要。"},
  {"id":"read-005","type":"reading","kind":"passage","score":2,"bank":"人物/社会","passage":"Mr. Wang is a 45-year-old engineer who works for a computer company in Beijing. He gets up at six every morning and goes to work by subway. In his free time, he enjoys reading and playing basketball with his son. He plans to travel abroad next summer.","stem":"What does Mr. Wang do?","options":[{"key":"A","text":"He is a teacher."},{"key":"B","text":"He is a doctor."},{"key":"C","text":"He is an engineer."},{"key":"D","text":"He is a manager."}],"answer":"C","explanation":"文中“Mr. Wang is a 45-year-old engineer”，他是一名工程师。"},
  {"id":"read-006","type":"reading","kind":"passage","score":2,"bank":"人物/社会","passage":"Mr. Wang is a 45-year-old engineer who works for a computer company in Beijing. He gets up at six every morning and goes to work by subway. In his free time, he enjoys reading and playing basketball with his son. He plans to travel abroad next summer.","stem":"What does he plan to do next summer?","options":[{"key":"A","text":"Find a new job."},{"key":"B","text":"Travel abroad."},{"key":"C","text":"Play basketball."},{"key":"D","text":"Read more books."}],"answer":"B","explanation":"文中“He plans to travel abroad next summer”，计划明年夏天出国旅行。"},
  {"id":"read-101","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Notice\n\nBecause of the National Day holiday, the school library will change its opening hours. From October 1 to October 7, the library will be open only from 9:00 a.m. to 4:00 p.m. During these seven days, the reading room on the second floor will be closed for cleaning. Students who need to borrow books are advised to come before September 30. All books borrowed before the holiday can be kept for two more weeks.","stem":"How long will the library's opening hours be during the holiday?","options":[{"key":"A","text":"From 8:00 a.m. to 5:00 p.m."},{"key":"B","text":"From 9:00 a.m. to 4:00 p.m."},{"key":"C","text":"From 9:00 a.m. to 5:00 p.m."},{"key":"D","text":"From 10:00 a.m. to 4:00 p.m."}],"answer":"B","explanation":"通知写明“the library will be open only from 9:00 a.m. to 4:00 p.m.”，假期开馆时间为上午 9 点到下午 4 点。"},
  {"id":"read-102","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Notice\n\nBecause of the National Day holiday, the school library will change its opening hours. From October 1 to October 7, the library will be open only from 9:00 a.m. to 4:00 p.m. During these seven days, the reading room on the second floor will be closed for cleaning. Students who need to borrow books are advised to come before September 30. All books borrowed before the holiday can be kept for two more weeks.","stem":"What will happen to the reading room on the second floor?","options":[{"key":"A","text":"It will be moved to the first floor."},{"key":"B","text":"It will be open for 24 hours."},{"key":"C","text":"It will be closed for cleaning."},{"key":"D","text":"It will be used for a meeting."}],"answer":"C","explanation":"文中“the reading room on the second floor will be closed for cleaning”，二楼阅览室因清洁而关闭。"},
  {"id":"read-103","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Notice\n\nBecause of the National Day holiday, the school library will change its opening hours. From October 1 to October 7, the library will be open only from 9:00 a.m. to 4:00 p.m. During these seven days, the reading room on the second floor will be closed for cleaning. Students who need to borrow books are advised to come before September 30. All books borrowed before the holiday can be kept for two more weeks.","stem":"What are students advised to do?","options":[{"key":"A","text":"Borrow books before September 30."},{"key":"B","text":"Return all books before October 1."},{"key":"C","text":"Read only in the reading room."},{"key":"D","text":"Buy their own textbooks."}],"answer":"A","explanation":"文中“Students who need to borrow books are advised to come before September 30”，建议借书的同学在 9 月 30 日前来。"},
  {"id":"read-104","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Sunrise English Training Center\n\nDo you want to speak English more confidently? Our evening classes start on March 5 and run for ten weeks. Each class lasts two hours, from 7:00 p.m. to 9:00 p.m., twice a week. The course fee is 800 yuan, including all teaching materials. If you register before February 25, you can get a 10% discount. Small classes of no more than twelve students make sure everyone gets enough practice. Call 6677-8899 or visit our website for more information.","stem":"How long does each class last?","options":[{"key":"A","text":"One hour."},{"key":"B","text":"Two hours."},{"key":"C","text":"Three hours."},{"key":"D","text":"Ten weeks."}],"answer":"B","explanation":"广告中“Each class lasts two hours”，每节课两小时。ten weeks 是课程总时长，不是单节课时长。"},
  {"id":"read-105","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Sunrise English Training Center\n\nDo you want to speak English more confidently? Our evening classes start on March 5 and run for ten weeks. Each class lasts two hours, from 7:00 p.m. to 9:00 p.m., twice a week. The course fee is 800 yuan, including all teaching materials. If you register before February 25, you can get a 10% discount. Small classes of no more than twelve students make sure everyone gets enough practice. Call 6677-8899 or visit our website for more information.","stem":"What advantage can students get if they register before February 25?","options":[{"key":"A","text":"A free textbook."},{"key":"B","text":"A 10% discount."},{"key":"C","text":"A free extra class."},{"key":"D","text":"A better teacher."}],"answer":"B","explanation":"广告中“If you register before February 25, you can get a 10% discount”，2 月 25 日前报名可享九折优惠。"},
  {"id":"read-106","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Sunrise English Training Center\n\nDo you want to speak English more confidently? Our evening classes start on March 5 and run for ten weeks. Each class lasts two hours, from 7:00 p.m. to 9:00 p.m., twice a week. The course fee is 800 yuan, including all teaching materials. If you register before February 25, you can get a 10% discount. Small classes of no more than twelve students make sure everyone gets enough practice. Call 6677-8899 or visit our website for more information.","stem":"What is one benefit of the small class size?","options":[{"key":"A","text":"The course is free of charge."},{"key":"B","text":"The class time is shorter."},{"key":"C","text":"Every student gets enough practice."},{"key":"D","text":"Students need not buy materials."}],"answer":"C","explanation":"文中“Small classes of no more than twelve students make sure everyone gets enough practice”，小班（不超过 12 人）保证每人有充分练习机会。"},
  {"id":"read-107","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Dear Mr. Green,\n\nThank you for your e-mail of May 6. We are pleased to confirm your booking for a single room from June 10 to June 14. The room rate is 260 yuan per night, including breakfast. As you requested, we have arranged a room on a quiet floor. Please note that check-in time is after 2:00 p.m. If you arrive earlier, you may leave your luggage at the front desk. We look forward to welcoming you.\n\nYours sincerely,\nAnna Lee\nReservations Manager","stem":"What is Mr. Green's booking for?","options":[{"key":"A","text":"A double room for four nights."},{"key":"B","text":"A single room for four nights."},{"key":"C","text":"A single room for five nights."},{"key":"D","text":"A meeting room for one day."}],"answer":"B","explanation":"信中“a single room from June 10 to June 14”，即 6 月 10 日至 14 日单人间，共 4 晚。"},
  {"id":"read-108","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Dear Mr. Green,\n\nThank you for your e-mail of May 6. We are pleased to confirm your booking for a single room from June 10 to June 14. The room rate is 260 yuan per night, including breakfast. As you requested, we have arranged a room on a quiet floor. Please note that check-in time is after 2:00 p.m. If you arrive earlier, you may leave your luggage at the front desk. We look forward to welcoming you.\n\nYours sincerely,\nAnna Lee\nReservations Manager","stem":"What does the room rate include?","options":[{"key":"A","text":"Breakfast."},{"key":"B","text":"Lunch and dinner."},{"key":"C","text":"Airport pick-up."},{"key":"D","text":"Laundry service."}],"answer":"A","explanation":"信中“The room rate is 260 yuan per night, including breakfast”，房费含早餐。"},
  {"id":"read-109","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Dear Mr. Green,\n\nThank you for your e-mail of May 6. We are pleased to confirm your booking for a single room from June 10 to June 14. The room rate is 260 yuan per night, including breakfast. As you requested, we have arranged a room on a quiet floor. Please note that check-in time is after 2:00 p.m. If you arrive earlier, you may leave your luggage at the front desk. We look forward to welcoming you.\n\nYours sincerely,\nAnna Lee\nReservations Manager","stem":"What can Mr. Green do if he arrives before 2:00 p.m.?","options":[{"key":"A","text":"Check in at once."},{"key":"B","text":"Wait in the dining hall."},{"key":"C","text":"Leave his luggage at the front desk."},{"key":"D","text":"Change to another room."}],"answer":"C","explanation":"信中“If you arrive earlier, you may leave your luggage at the front desk”，提前到达可把行李寄存在前台。"},
  {"id":"read-110","type":"reading","kind":"passage","score":2,"bank":"科普说明","passage":"Air Cleaner Model KX-200\n\nThe KX-200 is a small air cleaner designed for rooms of 15 to 25 square meters. It removes dust, smoke and bad smells from the air in about twenty minutes. The machine works very quietly, so you can use it while sleeping or working. Please clean the filter once a month with warm water, and replace it every twelve months. Do not put the machine near a wall or a window. If the red light comes on, the filter needs cleaning.","stem":"What is the KX-200 designed for?","options":[{"key":"A","text":"Large halls of over 50 square meters."},{"key":"B","text":"Rooms of 15 to 25 square meters."},{"key":"C","text":"Outdoor gardens."},{"key":"D","text":"Restaurants and kitchens."}],"answer":"B","explanation":"说明书写“designed for rooms of 15 to 25 square meters”，适用于 15 至 25 平方米的房间。"},
  {"id":"read-111","type":"reading","kind":"passage","score":2,"bank":"科普说明","passage":"Air Cleaner Model KX-200\n\nThe KX-200 is a small air cleaner designed for rooms of 15 to 25 square meters. It removes dust, smoke and bad smells from the air in about twenty minutes. The machine works very quietly, so you can use it while sleeping or working. Please clean the filter once a month with warm water, and replace it every twelve months. Do not put the machine near a wall or a window. If the red light comes on, the filter needs cleaning.","stem":"How often should the filter be cleaned?","options":[{"key":"A","text":"Once a week."},{"key":"B","text":"Once a month."},{"key":"C","text":"Once a year."},{"key":"D","text":"Every two years."}],"answer":"B","explanation":"文中“clean the filter once a month with warm water”，滤网每月清洗一次；每 12 个月更换（replace）一次。"},
  {"id":"read-112","type":"reading","kind":"passage","score":2,"bank":"科普说明","passage":"Air Cleaner Model KX-200\n\nThe KX-200 is a small air cleaner designed for rooms of 15 to 25 square meters. It removes dust, smoke and bad smells from the air in about twenty minutes. The machine works very quietly, so you can use it while sleeping or working. Please clean the filter once a month with warm water, and replace it every twelve months. Do not put the machine near a wall or a window. If the red light comes on, the filter needs cleaning.","stem":"What does the red light mean?","options":[{"key":"A","text":"The machine is too hot."},{"key":"B","text":"The room is too small."},{"key":"C","text":"The filter needs cleaning."},{"key":"D","text":"The machine is turned off."}],"answer":"C","explanation":"文中“If the red light comes on, the filter needs cleaning”，红灯亮表示滤网需要清洗。"},
  {"id":"read-113","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Resume\n\nName: Chen Hao\nAge: 24\nEducation: 2020-2023, Sunshine Vocational College, major in Business English\nSkills: English (CET-4), computer operation, office software\nExperience: 2023-2025, sales assistant at Far East Trading Company, in charge of customer e-mails and orders\nHobbies: basketball, photography\nE-mail: chenhao@mail.com\n\nI am looking for a position where I can use my language skills and my experience in international trade.","stem":"What did Chen Hao major in?","options":[{"key":"A","text":"Computer science."},{"key":"B","text":"Business English."},{"key":"C","text":"International trade."},{"key":"D","text":"Photography."}],"answer":"B","explanation":"简历中“major in Business English”，专业为商务英语。"},
  {"id":"read-114","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Resume\n\nName: Chen Hao\nAge: 24\nEducation: 2020-2023, Sunshine Vocational College, major in Business English\nSkills: English (CET-4), computer operation, office software\nExperience: 2023-2025, sales assistant at Far East Trading Company, in charge of customer e-mails and orders\nHobbies: basketball, photography\nE-mail: chenhao@mail.com\n\nI am looking for a position where I can use my language skills and my experience in international trade.","stem":"What was Chen Hao in charge of in his last job?","options":[{"key":"A","text":"Customer e-mails and orders."},{"key":"B","text":"Training new workers."},{"key":"C","text":"Designing new products."},{"key":"D","text":"Testing computer programs."}],"answer":"A","explanation":"简历中“in charge of customer e-mails and orders”，负责客户邮件和订单。"},
  {"id":"read-115","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Resume\n\nName: Chen Hao\nAge: 24\nEducation: 2020-2023, Sunshine Vocational College, major in Business English\nSkills: English (CET-4), computer operation, office software\nExperience: 2023-2025, sales assistant at Far East Trading Company, in charge of customer e-mails and orders\nHobbies: basketball, photography\nE-mail: chenhao@mail.com\n\nI am looking for a position where I can use my language skills and my experience in international trade.","stem":"What kind of position is Chen Hao looking for?","options":[{"key":"A","text":"A part-time job in a school."},{"key":"B","text":"A job using his language skills."},{"key":"C","text":"A job as a basketball coach."},{"key":"D","text":"A job in a photography studio."}],"answer":"B","explanation":"文末“I am looking for a position where I can use my language skills and my experience in international trade”，希望找能发挥语言能力和外贸经验的职位。"},
  {"id":"read-116","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Train Timetable (Beijing South Railway Station)\n\nG101: to Shanghai, departure 07:00, arrival 12:38, 553 yuan\nG105: to Shanghai, departure 08:05, arrival 13:40, 553 yuan\nG201: to Jinan, departure 09:20, arrival 11:05, 185 yuan\nD301: to Nanjing, departure 10:15, arrival 14:50, 445 yuan\n\nNotes: Passengers should arrive at the station thirty minutes before departure. Tickets can be booked online fifteen days in advance. Children under 1.2 metres travel free.","stem":"Which train goes to Jinan?","options":[{"key":"A","text":"G101."},{"key":"B","text":"G105."},{"key":"C","text":"G201."},{"key":"D","text":"D301."}],"answer":"C","explanation":"时刻表中“G201: to Jinan”，G201 次开往济南。"},
  {"id":"read-117","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Train Timetable (Beijing South Railway Station)\n\nG101: to Shanghai, departure 07:00, arrival 12:38, 553 yuan\nG105: to Shanghai, departure 08:05, arrival 13:40, 553 yuan\nG201: to Jinan, departure 09:20, arrival 11:05, 185 yuan\nD301: to Nanjing, departure 10:15, arrival 14:50, 445 yuan\n\nNotes: Passengers should arrive at the station thirty minutes before departure. Tickets can be booked online fifteen days in advance. Children under 1.2 metres travel free.","stem":"When should passengers arrive at the station?","options":[{"key":"A","text":"Ten minutes before departure."},{"key":"B","text":"Thirty minutes before departure."},{"key":"C","text":"One hour before departure."},{"key":"D","text":"Fifteen days before departure."}],"answer":"B","explanation":"注意事项写明“Passengers should arrive at the station thirty minutes before departure”，应提前 30 分钟到站。"},
  {"id":"read-118","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"Train Timetable (Beijing South Railway Station)\n\nG101: to Shanghai, departure 07:00, arrival 12:38, 553 yuan\nG105: to Shanghai, departure 08:05, arrival 13:40, 553 yuan\nG201: to Jinan, departure 09:20, arrival 11:05, 185 yuan\nD301: to Nanjing, departure 10:15, arrival 14:50, 445 yuan\n\nNotes: Passengers should arrive at the station thirty minutes before departure. Tickets can be booked online fifteen days in advance. Children under 1.2 metres travel free.","stem":"Who can travel free?","options":[{"key":"A","text":"Students with a school card."},{"key":"B","text":"People over sixty years old."},{"key":"C","text":"Children under 1.2 metres."},{"key":"D","text":"Passengers who book online."}],"answer":"C","explanation":"注意事项写明“Children under 1.2 metres travel free”，身高 1.2 米以下儿童免费乘车。"},
  {"id":"read-119","type":"reading","kind":"passage","score":2,"bank":"科普说明","passage":"Sleep is as important to our health as food and water. Doctors suggest that adults sleep seven to eight hours each night. If you often sleep less than six hours, you may find it hard to concentrate and easy to get ill. To sleep better, try to go to bed and get up at the same time every day, and keep away from your mobile phone for half an hour before sleeping. Coffee in the afternoon can also keep you awake at night.","stem":"How many hours of sleep do doctors suggest for adults?","options":[{"key":"A","text":"Four to five hours."},{"key":"B","text":"Five to six hours."},{"key":"C","text":"Seven to eight hours."},{"key":"D","text":"Nine to ten hours."}],"answer":"C","explanation":"文中“Doctors suggest that adults sleep seven to eight hours each night”，医生建议成年人每晚睡 7 至 8 小时。"},
  {"id":"read-120","type":"reading","kind":"passage","score":2,"bank":"科普说明","passage":"Sleep is as important to our health as food and water. Doctors suggest that adults sleep seven to eight hours each night. If you often sleep less than six hours, you may find it hard to concentrate and easy to get ill. To sleep better, try to go to bed and get up at the same time every day, and keep away from your mobile phone for half an hour before sleeping. Coffee in the afternoon can also keep you awake at night.","stem":"What may happen if you often sleep less than six hours?","options":[{"key":"A","text":"You may become taller."},{"key":"B","text":"You may find it hard to concentrate."},{"key":"C","text":"You may eat more food."},{"key":"D","text":"You may sleep better at night."}],"answer":"B","explanation":"文中“you may find it hard to concentrate and easy to get ill”，长期睡眠不足会影响注意力和健康。"},
  {"id":"read-121","type":"reading","kind":"passage","score":2,"bank":"科普说明","passage":"Sleep is as important to our health as food and water. Doctors suggest that adults sleep seven to eight hours each night. If you often sleep less than six hours, you may find it hard to concentrate and easy to get ill. To sleep better, try to go to bed and get up at the same time every day, and keep away from your mobile phone for half an hour before sleeping. Coffee in the afternoon can also keep you awake at night.","stem":"According to the passage, what should you avoid before sleeping?","options":[{"key":"A","text":"Drinking warm water."},{"key":"B","text":"Using your mobile phone."},{"key":"C","text":"Taking a walk."},{"key":"D","text":"Opening the window."}],"answer":"B","explanation":"文中“keep away from your mobile phone for half an hour before sleeping”，睡前半小时应远离手机。"},
  {"id":"read-122","type":"reading","kind":"passage","score":2,"bank":"人物/社会","passage":"Liu Wei works as a delivery man in Hangzhou. Every morning he starts work at seven and rides his electric bike through the city, sending about 120 parcels a day. In summer the heat is terrible and in winter his hands are nearly frozen, but he seldom complains. “Many people are waiting for their parcels,” he says. “When they open the door and smile at me, I feel my work is worth doing.” Liu Wei has been doing this job for six years, and he has never been late for a delivery.","stem":"How many parcels does Liu Wei send a day?","options":[{"key":"A","text":"About 12."},{"key":"B","text":"About 100."},{"key":"C","text":"About 120."},{"key":"D","text":"About 200."}],"answer":"C","explanation":"文中“sending about 120 parcels a day”，他每天送约 120 个包裹。"},
  {"id":"read-123","type":"reading","kind":"passage","score":2,"bank":"人物/社会","passage":"Liu Wei works as a delivery man in Hangzhou. Every morning he starts work at seven and rides his electric bike through the city, sending about 120 parcels a day. In summer the heat is terrible and in winter his hands are nearly frozen, but he seldom complains. “Many people are waiting for their parcels,” he says. “When they open the door and smile at me, I feel my work is worth doing.” Liu Wei has been doing this job for six years, and he has never been late for a delivery.","stem":"Why does Liu Wei think his work is worth doing?","options":[{"key":"A","text":"Because he earns a lot of money."},{"key":"B","text":"Because customers smile at him."},{"key":"C","text":"Because the job is easy."},{"key":"D","text":"Because he can travel around China."}],"answer":"B","explanation":"文中他说“When they open the door and smile at me, I feel my work is worth doing”，顾客的笑容让他觉得工作有价值。"},
  {"id":"read-124","type":"reading","kind":"passage","score":2,"bank":"人物/社会","passage":"Liu Wei works as a delivery man in Hangzhou. Every morning he starts work at seven and rides his electric bike through the city, sending about 120 parcels a day. In summer the heat is terrible and in winter his hands are nearly frozen, but he seldom complains. “Many people are waiting for their parcels,” he says. “When they open the door and smile at me, I feel my work is worth doing.” Liu Wei has been doing this job for six years, and he has never been late for a delivery.","stem":"How long has Liu Wei been a delivery man?","options":[{"key":"A","text":"For one year."},{"key":"B","text":"For three years."},{"key":"C","text":"For six years."},{"key":"D","text":"For twelve years."}],"answer":"C","explanation":"文中“Liu Wei has been doing this job for six years”，他做这份工作已六年。"},
  {"id":"read-125","type":"reading","kind":"passage","score":2,"bank":"人物/社会","passage":"Today more and more people look at their mobile phones when they are with friends. A recent study of 2,000 young people found that nearly half of them check their phones at least once every ten minutes during a meal. Doctors say this habit can make people feel lonely even when they are together. Some restaurants now offer a small discount to customers who put their phones in a box during the meal. The idea is simple: talk to the person in front of you.","stem":"What did the recent study find?","options":[{"key":"A","text":"Young people seldom eat out."},{"key":"B","text":"Nearly half of the young people check phones very often during meals."},{"key":"C","text":"Mobile phones are becoming cheaper."},{"key":"D","text":"Restaurants are closing earlier."}],"answer":"B","explanation":"文中“nearly half of them check their phones at least once every ten minutes during a meal”，近半数年轻人吃饭时频繁看手机。"},
  {"id":"read-126","type":"reading","kind":"passage","score":2,"bank":"人物/社会","passage":"Today more and more people look at their mobile phones when they are with friends. A recent study of 2,000 young people found that nearly half of them check their phones at least once every ten minutes during a meal. Doctors say this habit can make people feel lonely even when they are together. Some restaurants now offer a small discount to customers who put their phones in a box during the meal. The idea is simple: talk to the person in front of you.","stem":"What do doctors say about this habit?","options":[{"key":"A","text":"It makes people feel lonely."},{"key":"B","text":"It helps people make friends."},{"key":"C","text":"It is good for the eyes."},{"key":"D","text":"It saves a lot of money."}],"answer":"A","explanation":"文中“Doctors say this habit can make people feel lonely even when they are together”，医生认为该习惯让人即使相聚也感到孤独。"},
  {"id":"read-127","type":"reading","kind":"passage","score":2,"bank":"人物/社会","passage":"Today more and more people look at their mobile phones when they are with friends. A recent study of 2,000 young people found that nearly half of them check their phones at least once every ten minutes during a meal. Doctors say this habit can make people feel lonely even when they are together. Some restaurants now offer a small discount to customers who put their phones in a box during the meal. The idea is simple: talk to the person in front of you.","stem":"How do some restaurants encourage customers to put phones away?","options":[{"key":"A","text":"By offering a small discount."},{"key":"B","text":"By asking them to leave."},{"key":"C","text":"By serving free drinks."},{"key":"D","text":"By playing loud music."}],"answer":"A","explanation":"文中“Some restaurants now offer a small discount to customers who put their phones in a box during the meal”，餐厅以小幅折扣鼓励顾客放下手机。"},
  {"id":"read-128","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"MEMO\nTo: All staff of the Sales Department\nFrom: Human Resources Office\nDate: April 8\nSubject: Training on the new sales system\n\nThe company will introduce a new sales system next month. All staff of the Sales Department must attend a two-day training course on April 22 and April 23, from 9:00 a.m. to 4:30 p.m. in Room 305. Please bring your own laptop. Lunch will be provided by the company. If you cannot attend for some reason, please report to Ms. Zhang before April 18. After the training, there will be a short test.","stem":"Who must attend the training course?","options":[{"key":"A","text":"All staff of the Sales Department."},{"key":"B","text":"Only new employees."},{"key":"C","text":"All managers of the company."},{"key":"D","text":"Staff of the Human Resources Office."}],"answer":"A","explanation":"备忘录写明“All staff of the Sales Department must attend a two-day training course”，销售部全体员工必须参加。"},
  {"id":"read-129","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"MEMO\nTo: All staff of the Sales Department\nFrom: Human Resources Office\nDate: April 8\nSubject: Training on the new sales system\n\nThe company will introduce a new sales system next month. All staff of the Sales Department must attend a two-day training course on April 22 and April 23, from 9:00 a.m. to 4:30 p.m. in Room 305. Please bring your own laptop. Lunch will be provided by the company. If you cannot attend for some reason, please report to Ms. Zhang before April 18. After the training, there will be a short test.","stem":"What should the staff bring to the training?","options":[{"key":"A","text":"Their own laptop."},{"key":"B","text":"Their own lunch."},{"key":"C","text":"A notebook and a pen."},{"key":"D","text":"Their ID card."}],"answer":"A","explanation":"备忘录写明“Please bring your own laptop”，需自带笔记本电脑；午餐由公司提供。"},
  {"id":"read-130","type":"reading","kind":"passage","score":2,"bank":"实用文体","passage":"MEMO\nTo: All staff of the Sales Department\nFrom: Human Resources Office\nDate: April 8\nSubject: Training on the new sales system\n\nThe company will introduce a new sales system next month. All staff of the Sales Department must attend a two-day training course on April 22 and April 23, from 9:00 a.m. to 4:30 p.m. in Room 305. Please bring your own laptop. Lunch will be provided by the company. If you cannot attend for some reason, please report to Ms. Zhang before April 18. After the training, there will be a short test.","stem":"What will happen after the training?","options":[{"key":"A","text":"A short test."},{"key":"B","text":"A dinner party."},{"key":"C","text":"A long holiday."},{"key":"D","text":"A new manager will come."}],"answer":"A","explanation":"备忘录最后一句“After the training, there will be a short test”，培训后有简短测试。"},

  /* ===================== 翻译（translation）· 30 题 ===================== */
  {"id":"tra-001","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"The library is open from Monday to Friday.","answer":["图书馆周一到周五开放","图书馆星期一至星期五开放"],"explanation":"open 此处意为“开放、营业”。注意星期表达的转换。"},
  {"id":"tra-002","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"Please let me know if you need any help.","answer":["如果你需要任何帮助请告诉我","如需要帮助请告知我","如果你需要帮助请让我知道"],"explanation":"if 引导条件句“如果”。let me know“让我知道/告诉我”。"},
  {"id":"tra-003","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"The company was set up in 2005.","answer":["这家公司成立于2005年","公司创立于2005年"],"explanation":"was set up 被动语态，表示“被建立/成立”。"},
  {"id":"tra-004","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"It is necessary to arrive at the station before 8 o'clock.","answer":["有必要在8点前到达车站","必须在8点前到达车站"],"explanation":"It is necessary to do sth. 句型“做某事是必要的”。"},
  {"id":"tra-005","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"The harder you work, the better result you will get.","answer":["你越努力结果就越好","你工作越努力取得的成果越好"],"explanation":"the + 比较级, the + 比较级 句型“越……就越……”。"},
  {"id":"tra-101","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"Please fill in the form and return it to the office before Friday.","answer":["请填写表格并在周五前交回办公室","请填好表格并在周五之前交到办公室"],"explanation":"fill in 意为“填写”，return...to... 意为“把……交回/归还给……”。before Friday 译为“周五之前”。"},
  {"id":"tra-102","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"We are looking forward to hearing from you soon.","answer":["我们期待尽快收到您的来信","期待早日收到您的回复"],"explanation":"look forward to 意为“期待”，后接动名词；hear from sb. 意为“收到某人的来信/消息”。这是商务信函常用结束语。"},
  {"id":"tra-103","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"The meeting has been put off until next Monday.","answer":["会议已推迟到下周一","会议被延期至下星期一"],"explanation":"has been put off 为现在完成时的被动语态，put off 意为“推迟、延期”。until next Monday 表示推迟到的时间。"},
  {"id":"tra-104","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"This machine is easy to operate and safe to use.","answer":["这台机器操作简单使用安全","这种机器易于操作且使用安全"],"explanation":"“be + 形容词 + to do”结构，不定式主动形式表被动含义：easy to operate 意为“容易操作”。"},
  {"id":"tra-105","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"Please turn off your mobile phone during the examination.","answer":["考试期间请关闭手机","考试时请关掉你的手机"],"explanation":"turn off 意为“关闭（电器）”；during the examination 意为“考试期间”，翻译时前置更符合汉语习惯。"},
  {"id":"tra-106","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"The goods you ordered will be delivered within three days.","answer":["您订购的货物将在三天内送达","你订的货三天内发货"],"explanation":"you ordered 是省略了 that 的定语从句，修饰 the goods；within three days 意为“三天之内”。"},
  {"id":"tra-107","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"I would like to book a double room for two nights.","answer":["我想预订一间双人房住两晚","我要订一个双人间住两个晚上"],"explanation":"I would like to do sth. 意为“我想要做某事”，语气比 want 更礼貌；book 作动词意为“预订”。"},
  {"id":"tra-108","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"Smoking is not allowed anywhere in the building.","answer":["楼内任何地方都不准吸烟","本楼内禁止吸烟"],"explanation":"is not allowed 为被动语态，意为“不被允许”；anywhere in the building 表示“楼内任何地方”。"},
  {"id":"tra-109","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"The price of the product includes tax and delivery.","answer":["产品价格包含税费和运费","该产品的价格含税并包含送货费"],"explanation":"include 意为“包括、包含”；tax 意为“税”，delivery 在此指“送货、运费”。"},
  {"id":"tra-110","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"Could you tell me how to get to the railway station?","answer":["你能告诉我怎么去火车站吗","请问到火车站怎么走"],"explanation":"Could you tell me... 是礼貌的问路句型；how to get to... 为“疑问词 + 不定式”结构，意为“如何去……”。"},
  {"id":"tra-111","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"He has worked in this company since he graduated from college.","answer":["他大学毕业后一直在这家公司工作","自大学毕业以来他就在这家公司上班"],"explanation":"since 引导时间状语从句，主句用现在完成时，表示从过去某时一直持续到现在。"},
  {"id":"tra-112","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"The report should be handed in before the end of this month.","answer":["报告应在本月底前上交","这份报告必须在这个月底之前提交"],"explanation":"should be handed in 为“情态动词 + 被动语态”，意为“应当被上交”；hand in 意为“上交、提交”。"},
  {"id":"tra-113","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"Our company is going to take part in the trade fair in Shanghai.","answer":["我们公司将参加上海的贸易博览会","我公司打算参加上海的展销会"],"explanation":"be going to 表示计划、打算；take part in 意为“参加”；trade fair 意为“贸易博览会、展销会”。"},
  {"id":"tra-114","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"It took him two hours to finish the work.","answer":["他花了两个小时完成这项工作","完成这项工作花了他两个小时"],"explanation":"It takes sb. some time to do sth. 句型，意为“某人花多长时间做某事”，it 为形式主语。"},
  {"id":"tra-115","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"You had better see a doctor at once.","answer":["你最好马上去看医生","你最好立刻去看病"],"explanation":"had better do sth. 意为“最好做某事”，后接动词原形；at once 意为“立刻、马上”。"},
  {"id":"tra-116","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"The new library is much larger than the old one.","answer":["新图书馆比旧的大得多","这座新图书馆比那座旧图书馆大很多"],"explanation":"much 修饰比较级 larger，表示程度“大得多”；the old one 中 one 代替前面的 library，避免重复。"},
  {"id":"tra-117","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"We are sorry to inform you that your order has been cancelled.","answer":["很抱歉通知您您的订单已被取消","我们遗憾地通知你订单已经取消了"],"explanation":"be sorry to inform you 是商务信函常用的致歉表达；has been cancelled 为现在完成时被动语态。"},
  {"id":"tra-118","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"In order to save time, we decided to travel by air.","answer":["为了节省时间我们决定乘飞机出行","为了省时间我们决定坐飞机去"],"explanation":"in order to 引导目的状语，意为“为了”；by air 意为“乘飞机”，类似的还有 by train、by sea。"},
  {"id":"tra-119","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"The manager asked me to send him the sales figures this afternoon.","answer":["经理让我今天下午把销售数据发给他","经理要求我今天下午把销售数字送给他"],"explanation":"ask sb. to do sth. 意为“让某人做某事”；sales figures 意为“销售数据/销售数字”。"},
  {"id":"tra-120","type":"translation","kind":"translate","score":3,"bank":"句子英译汉","stem":"请将下列句子翻译成汉语：","passage":"If you have any questions, please feel free to contact us.","answer":["如有任何问题请随时与我们联系","如果您有任何疑问请随时联系我们"],"explanation":"if 引导条件状语从句；feel free to do sth. 意为“尽管做某事、随时做某事”，是礼貌用语。"},
  {"id":"tra-121","type":"translation","kind":"translate","score":3,"bank":"段落英译汉","stem":"请将下列句子翻译成汉语：","passage":"Thank you for your interest in our products. We have sent you our latest price list by e-mail. If you need any further information, please do not hesitate to call us.","answer":["感谢您对我们产品的关注我们已通过电子邮件将最新价格表发给您如需更多信息请随时致电我们","感谢您对我们产品感兴趣我们已用邮件把最新报价单寄给您如有其他需要请尽管来电"],"explanation":"interest in 意为“对……的兴趣”；price list 意为“价格表、报价单”；do not hesitate to do sth. 意为“尽管做某事”，是商务函电常见客套语。"},
  {"id":"tra-122","type":"translation","kind":"translate","score":3,"bank":"段落英译汉","stem":"请将下列句子翻译成汉语：","passage":"Our school will hold a job fair next Wednesday. More than thirty companies will take part in it. Students who are going to graduate this summer are welcome to attend.","answer":["我们学校下周三将举办招聘会三十多家公司将参加今年夏天毕业的学生欢迎参加","我校下周三举行就业洽谈会有三十多家公司参加即将于今年夏季毕业的学生欢迎前来"],"explanation":"job fair 意为“招聘会”；take part in 意为“参加”；who 引导定语从句修饰 students。注意“welcome to attend”译作“欢迎参加”。"},
  {"id":"tra-123","type":"translation","kind":"translate","score":3,"bank":"段落英译汉","stem":"请将下列句子翻译成汉语：","passage":"Please note that the office will be closed during the Spring Festival. If you need any service, please call our hotline 400-1234-567.","answer":["请注意春节期间办公室将停止办公如需服务请拨打我们的热线400-1234-567","请注意本办公室春节期间不办公如您需要任何服务请致电服务热线"],"explanation":"Please note that... 是通知中的提示用语，意为“请注意……”；hotline 意为“热线电话”。"},
  {"id":"tra-124","type":"translation","kind":"translate","score":3,"bank":"段落英译汉","stem":"请将下列句子翻译成汉语：","passage":"The train was late because of the heavy snow. As a result, we missed our flight and had to wait at the airport for six hours.","answer":["由于大雪火车晚点了结果我们错过了航班不得不在机场等了六个小时","因为大雪火车误点因此我们没赶上飞机只好在机场等了六小时"],"explanation":"because of 后接名词短语表示原因；as a result 意为“结果、因此”；miss 在此意为“错过、没赶上”。"},
  {"id":"tra-125","type":"translation","kind":"translate","score":3,"bank":"段落英译汉","stem":"请将下列句子翻译成汉语：","passage":"Learning a foreign language is not easy, but it is useful for your future job. The more you practise, the more confident you will become.","answer":["学一门外语并不容易但它对你将来的工作很有用你练习得越多就会越自信","学习外语不容易然而对今后的工作很有帮助练得越多就会越有信心"],"explanation":"动名词短语 Learning a foreign language 作主语，谓语用单数 is；the more..., the more... 意为“越……就越……”。"},

  /* ===================== 写作（writing）· 19 题 ===================== */
  {"id":"wri-001","type":"writing","kind":"writing","score":15,"bank":"应用文·便条","stem":"假设你是李明。请用英语写一封请假条（约 30 词），向老师 Mr. Smith 说明你因感冒不能来上课，并请求请假一天。","answer":null,"reference":"Dear Mr. Smith,\n\nI'm sorry to tell you that I can't come to class today because I've caught a cold. I would like to ask for a day off. Thank you.\n\nLi Ming","explanation":"请假条需包含：称呼、请假原因（感冒）、请假时长（一天）、署名。语气礼貌即可，语法正确、要点齐全即可得分。","options":[]},
  {"id":"wri-002","type":"writing","kind":"writing","score":15,"bank":"应用文·通知","stem":"请写一则英文通知（约 40 词），告知全体同学本周五下午 3 点在会议室举行英语讲座，欢迎参加。","answer":null,"reference":"NOTICE\n\nAn English lecture will be held at 3:00 p.m. this Friday in the meeting room. All the students are welcome to attend it.\n\nStudents' Union","explanation":"通知需包含：事件（英语讲座）、时间（本周五下午3点）、地点（会议室）、欢迎参加等信息，落款可选。","options":[]},
  {"id":"wri-003","type":"writing","kind":"writing","score":15,"bank":"应用文·信函","stem":"假设你是王芳，写一封约 50 词的英文邮件给客户 John，感谢对方订购贵公司产品，并告知货物将于下周发出。","answer":null,"reference":"Dear John,\n\nThank you very much for ordering our products. We are glad to tell you that the goods will be sent to you next week. If you have any questions, please feel free to contact us.\n\nWang Fang","explanation":"商务信函需包含：感谢订购、发货时间（下周）、可提供联系方式，语气礼貌得体。","options":[]},
  {"id":"wri-004","type":"writing","kind":"writing","score":15,"bank":"填表","stem":"根据以下信息填写英文表格影片名、导演、主演、片长：\n影片《Hero》由张艺谋执导，主演李连杰，片长约 99 分钟。","options":[],"answer":null,"reference":"Film: Hero\nDirector: Zhang Yimou\nLeading actor: Li Lianjie (Jet Li)\nRunning time: about 99 minutes","explanation":"此类填表题按信息逐项转写即可，注意人名拼写和片长格式。"},
  {"id":"wri-101","type":"writing","kind":"writing","score":15,"bank":"应用文·便条","stem":"假设你是张伟。请用英语给你的同事 Mary 写一张留言条（约 30 词），告诉她你临时有事外出，下午三点回来，请她把收到的文件放在你桌上。","answer":null,"reference":"Dear Mary,\n\nI have to go out on business and will be back at 3:00 p.m. Please leave the documents you received on my desk. Thank you.\n\nZhang Wei","explanation":"留言条（Message/Note）要点：称呼、事由（临时外出）、返回时间（下午 3 点）、请求事项（把文件放桌上）、署名。语言简洁、语气礼貌即得分。","options":[]},
  {"id":"wri-102","type":"writing","kind":"writing","score":15,"bank":"应用文·通知","stem":"请以学生会名义写一则英文通知（约 40 词），告知全体学生学校将于 5 月 15 日晚上 7 点在大礼堂举办英语演讲比赛，欢迎报名参加，报名截止日期为 5 月 10 日。","answer":null,"reference":"NOTICE\n\nAn English speech contest will be held in the Main Hall at 7:00 p.m. on May 15. All students are welcome to take part in it. Those who want to join should sign up before May 10.\n\nStudents' Union","explanation":"通知要点：标题 NOTICE、活动名称（英语演讲比赛）、时间（5月15日晚7点）、地点（大礼堂）、报名方式与截止日期、落款。缺项按比例扣分。","options":[]},
  {"id":"wri-103","type":"writing","kind":"writing","score":15,"bank":"应用文·信函","stem":"假设你是李华。请用英语给你的一位外国朋友 Peter 写一封邀请函（约 50 词），邀请他参加你下周六晚上的生日聚会，并告诉他聚会的地点和开始时间。","answer":null,"reference":"Dear Peter,\n\nI would like to invite you to my birthday party next Saturday evening. It will start at 6:30 p.m. at my home. I hope you can come and we will have a good time together.\n\nYours,\nLi Hua","explanation":"邀请函要点：称呼、邀请事由（生日聚会）、时间（下周六晚）、地点（家中）、期盼对方参加、署名。注意 I would like to invite you to... 是标准句式。","options":[]},
  {"id":"wri-104","type":"writing","kind":"writing","score":15,"bank":"应用文·信函","stem":"假设你是王明。请用英语给你的老师 Mr. Brown 写一封感谢信（约 40 词），感谢他在英语学习上给予你的帮助，并表示你会继续努力。","answer":null,"reference":"Dear Mr. Brown,\n\nThank you very much for your help with my English study. With your help, I have made great progress. I will keep working hard and try to do better.\n\nYours sincerely,\nWang Ming","explanation":"感谢信要点：称呼、致谢原因（英语学习上的帮助）、具体说明收获（取得进步）、表示决心、署名。Thank you very much for... 为常用句式。","options":[]},
  {"id":"wri-105","type":"writing","kind":"writing","score":15,"bank":"应用文·信函","stem":"假设你是刘丹。请用英语给你的朋友 Jane 写一封道歉信（约 40 词），说明你因突然生病未能参加她的生日聚会，请她原谅。","answer":null,"reference":"Dear Jane,\n\nI am very sorry that I could not come to your birthday party because I was ill that day. Please accept my apology. I hope I can see you soon.\n\nYours,\nLiu Dan","explanation":"道歉信要点：称呼、说明未能赴约的事实、给出原因（生病）、明确道歉（Please accept my apology）、署名。语气诚恳即可。","options":[]},
  {"id":"wri-106","type":"writing","kind":"writing","score":15,"bank":"应用文·信函","stem":"假设你是陈杰。请用英语写一封求职信（约 60 词），应征某公司销售助理一职，说明你毕业于职业学校商务英语专业，有两年销售工作经验，希望得到面试机会。","answer":null,"reference":"Dear Sir or Madam,\n\nI am writing to apply for the position of sales assistant in your company. I graduated from a vocational college and my major was Business English. I have worked as a sales assistant for two years and I am good at communicating with customers. I would be grateful if you could give me a chance to have an interview.\n\nYours sincerely,\nChen Jie","explanation":"求职信要点：称呼（Dear Sir or Madam）、应聘职位、学历专业、工作经验与能力、表达面试愿望、署名。I am writing to apply for... 是标准开头。","options":[]},
  {"id":"wri-107","type":"writing","kind":"writing","score":15,"bank":"应用文·信函","stem":"假设你是李强。请用英语给某商场客服部写一封投诉信（约 50 词），说明你上周购买的手机使用三天后出现故障，要求更换新机或退款。","answer":null,"reference":"Dear Sir or Madam,\n\nI bought a mobile phone in your store last week. However, it stopped working after only three days. I am writing to ask for a new one or a refund. I hope you can deal with this matter as soon as possible.\n\nYours sincerely,\nLi Qiang","explanation":"投诉信要点：说明购买时间与商品、指出问题（三天后故障）、提出明确要求（换货或退款）、希望尽快处理、署名。语气应坚定但礼貌，避免辱骂性语言。","options":[]},
  {"id":"wri-108","type":"writing","kind":"writing","score":15,"bank":"应用文·信函","stem":"假设你是赵敏。请用英语写一封推荐信（约 50 词），向某公司推荐你的同学孙涛应聘翻译一职，说明他英语成绩优秀、工作认真负责。","answer":null,"reference":"Dear Sir or Madam,\n\nI am glad to recommend my classmate Sun Tao for the position of translator in your company. He is excellent in English and has passed CET-6. He is also a careful and responsible person. I am sure he will do the job well.\n\nYours sincerely,\nZhao Min","explanation":"推荐信要点：说明推荐人与被推荐人关系、应聘职位、被推荐人的能力与品质（英语优秀、认真负责）、表明信心、署名。recommend sb. for... 为常用句型。","options":[]},
  {"id":"wri-109","type":"writing","kind":"writing","score":15,"bank":"填表","stem":"请根据以下信息，用英语填写一张学生登记表（Student Registration Form）中的各项：姓名王丽，女，2005 年 3 月出生，专业商务英语，班级 2023 级 2 班，联系电话 13800001111，电子邮箱 wangli@mail.com。","answer":null,"reference":"Name: Wang Li\nSex: Female\nDate of birth: March, 2005\nMajor: Business English\nClass: Class 2, Grade 2023\nTelephone: 13800001111\nE-mail: wangli@mail.com","explanation":"填表题按项目逐条转写：姓名用拼音并注意姓在前、名在后且首字母大写；性别 Female；出生年月注意英文月份写法；专业、班级、电话、邮箱照抄。信息准确、格式规范即可得分。","options":[]},
  {"id":"wri-110","type":"writing","kind":"writing","score":15,"bank":"填表","stem":"请根据以下信息，用英语填写一张酒店入住登记表（Hotel Registration Form）：客人姓名李明，国籍中国，护照号 G12345678，入住日期 2025 年 8 月 10 日，退房日期 2025 年 8 月 13 日，房间类型单人间，房价每晚 280 元。","answer":null,"reference":"Guest name: Li Ming\nNationality: Chinese\nPassport number: G12345678\nDate of arrival: August 10, 2025\nDate of departure: August 13, 2025\nRoom type: Single room\nRoom rate: 280 yuan per night","explanation":"酒店登记表要点：姓名、国籍（用形容词 Chinese）、护照号、入住/退房日期（英文日期用月份 + 日 + 年）、房间类型、房价。注意 arrival/departure 与 check-in/check-out 的对应。","options":[]},
  {"id":"wri-111","type":"writing","kind":"writing","score":15,"bank":"应用文·便条","stem":"假设你是王涛。请用英语给同学 Lucy 写一张约 30 词的留言条，请她明天上午 9 点在教学楼门口等你，一起去图书馆还书。","answer":null,"reference":"Dear Lucy,\n\nWould you please wait for me at the gate of the teaching building at 9:00 tomorrow morning? We will go to the library to return the books together.\n\nWang Tao","explanation":"留言条要点：称呼、约定时间（明天上午 9 点）、地点（教学楼门口）、事项（一起去图书馆还书）、署名。Would you please... 表示委婉请求。","options":[]},
  {"id":"wri-112","type":"writing","kind":"writing","score":15,"bank":"应用文·便条","stem":"假设你是李娜。请用英语给经理 Mr. Smith 写一张请假条（约 35 词），说明你因家中有事需请假两天（6 月 3 日至 6 月 4 日），并保证回来后将补齐工作。","answer":null,"reference":"Dear Mr. Smith,\n\nI am writing to ask for two days' leave from June 3 to June 4, because I have something important to deal with at home. I will make up for the work when I come back.\n\nLi Na","explanation":"请假条要点：称呼、请假事由（家中有事）、请假起止时间（6月3日至4日）、请假天数、工作安排说明、署名。ask for... leave 为固定表达。","options":[]},
  {"id":"wri-113","type":"writing","kind":"writing","score":15,"bank":"应用文·贺卡","stem":"假设你是张华。请用英语给你的英语老师 Mrs. Green 写一张新年贺卡（约 30 词），祝她新年快乐、身体健康，并感谢她一年来的教导。","answer":null,"reference":"Dear Mrs. Green,\n\nHappy New Year! I wish you good health and happiness in the new year. Thank you for teaching me so patiently during the past year.\n\nZhang Hua","explanation":"贺卡要点：称呼、祝福语（Happy New Year!）、具体祝愿（身体健康、幸福）、感谢话语、署名。I wish you... 为祝愿常用句型。","options":[]},
  {"id":"wri-114","type":"writing","kind":"writing","score":15,"bank":"应用文·通知","stem":"请以公司办公室名义写一则英文通知（约 45 词），告知全体员工公司将于 4 月 20 日下午 2 点在会议室召开全体员工大会，请准时参加并携带笔记本。","answer":null,"reference":"NOTICE\n\nA general staff meeting will be held in the meeting room at 2:00 p.m. on April 20. All employees are required to attend it on time and bring a notebook with you.\n\nOffice of the Company","explanation":"通知要点：标题、会议名称（全体员工大会）、时间（4月20日下午2点）、地点（会议室）、参加要求（准时并带笔记本）、落款。be required to do sth. 表示“被要求做某事”。","options":[]},
  {"id":"wri-115","type":"writing","kind":"writing","score":15,"bank":"应用文·信函","stem":"假设你是某公司销售部职员周琳。请用英语给客户 Mr. White 写一封约 50 词的信，告知他本公司新产品将于下月上市，随信附上产品目录，欢迎他前来洽谈合作。","answer":null,"reference":"Dear Mr. White,\n\nI am glad to tell you that our new products will be on the market next month. I have enclosed our latest catalogue for your reference. You are warmly welcome to visit our company and talk about further cooperation.\n\nYours sincerely,\nZhou Lin","explanation":"商务信函要点：告知新产品上市时间、说明随信附上目录（enclose the catalogue）、表达合作意愿、署名。enclose 意为“随信附上”，be on the market 意为“上市”。","options":[]},

  /* ===================== 听力（listening）· 35 题 ===================== */
  {"id":"lis-001","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: Could you tell me where the post office is?","options":[{"key":"A","text":"It's next to the bank."},{"key":"B","text":"Yes, I like it."},{"key":"C","text":"It's five o'clock."},{"key":"D","text":"No, thank you."}],"answer":"A","explanation":"询问邮局位置，应回答位置“在银行旁边”。其余为答非所问。"},
  {"id":"lis-002","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: Would you like something to drink?","options":[{"key":"A","text":"Yes, a cup of coffee, please."},{"key":"B","text":"I'm going shopping."},{"key":"C","text":"It's very hot today."},{"key":"D","text":"See you tomorrow."}],"answer":"A","explanation":"询问是否要喝点什么，应回答想要什么饮品。"},
  {"id":"lis-003","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nW: What time does the train leave?\nM: It leaves at 9:30 in the morning.\nquestion: When does the train leave?","options":[{"key":"A","text":"At 9:00 a.m."},{"key":"B","text":"At 9:30 a.m."},{"key":"C","text":"At 9:30 p.m."},{"key":"D","text":"At 10:00 a.m."}],"answer":"B","explanation":"对话中男士明确说“It leaves at 9:30 in the morning”，火车上午 9:30 发车。"},
  {"id":"lis-004","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nM: What's the weather like today?\nW: It's sunny but a little windy.\nquestion: What's the weather like today?","options":[{"key":"A","text":"Rainy."},{"key":"B","text":"Snowy."},{"key":"C","text":"Sunny and windy."},{"key":"D","text":"Cloudy and cold."}],"answer":"C","explanation":"女士回答“It's sunny but a little windy”，天气晴朗但有风。"},
  {"id":"lis-005","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nW: Excuse me, how much is this T-shirt?\nM: It's 45 yuan.\nquestion: How much is the T-shirt?","options":[{"key":"A","text":"40 yuan."},{"key":"B","text":"45 yuan."},{"key":"C","text":"50 yuan."},{"key":"D","text":"15 yuan."}],"answer":"B","explanation":"男士回答“It's 45 yuan”，T 恤 45 元。"},
  {"id":"lis-101","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: What's the date today?","options":[{"key":"A","text":"It's Monday."},{"key":"B","text":"It's October 8."},{"key":"C","text":"It's half past nine."},{"key":"D","text":"It's fine today."}],"answer":"B","explanation":"What's the date 询问日期，应回答具体日期（10 月 8 日）。A 回答星期，C 回答时间，D 回答天气，均答非所问。"},
  {"id":"lis-102","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: How do you like the new teacher?","options":[{"key":"A","text":"She is very kind and patient."},{"key":"B","text":"Yes, I like teaching."},{"key":"C","text":"She teaches in Room 302."},{"key":"D","text":"I met her yesterday."}],"answer":"A","explanation":"How do you like...? 询问对某人/某物的看法，应回答评价（她和蔼又耐心）。注意此句不是提问“是否喜欢”，不能用 Yes/No 回答。"},
  {"id":"lis-103","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: Thank you for helping me with my homework.","options":[{"key":"A","text":"That's all right."},{"key":"B","text":"It's my homework."},{"key":"C","text":"Yes, please."},{"key":"D","text":"Never mind the homework."}],"answer":"A","explanation":"对感谢的应答常用 That's all right. / You're welcome. / Not at all.。B、D 均为答非所问，C 用于回应请求或提议。"},
  {"id":"lis-104","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: Excuse me, could you tell me where the manager's office is?","options":[{"key":"A","text":"Yes, I can manage it."},{"key":"B","text":"It's on the third floor."},{"key":"C","text":"The manager is out."},{"key":"D","text":"I'll take the office."}],"answer":"B","explanation":"问路句型 Where is...?，应答应给出具体位置。C 只说明经理外出，没有回答地点；A、D 与地点无关。"},
  {"id":"lis-105","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: Shall we go to the cinema this evening?","options":[{"key":"A","text":"Yes, I'd love to."},{"key":"B","text":"It's a good cinema."},{"key":"C","text":"I went there last year."},{"key":"D","text":"The film is two hours long."}],"answer":"A","explanation":"Shall we...? 用于提出建议，应答表示同意或拒绝，如 Yes, I'd love to. / Sorry, I can't.。"},
  {"id":"lis-106","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: I'm sorry I'm late for the meeting.","options":[{"key":"A","text":"That's quite all right. Come in, please."},{"key":"B","text":"The meeting is very important."},{"key":"C","text":"Yes, I was late too."},{"key":"D","text":"You're welcome to the meeting."}],"answer":"A","explanation":"对道歉的应答常用 That's all right. / It doesn't matter. / Never mind.。D 中的 You're welcome 用于回应感谢，不适用于道歉。"},
  {"id":"lis-107","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: How much does this dictionary cost?","options":[{"key":"A","text":"It has 500 pages."},{"key":"B","text":"It's 36 yuan."},{"key":"C","text":"I bought it yesterday."},{"key":"D","text":"It's very useful."}],"answer":"B","explanation":"How much 询问价格，应答必须给出价钱。A 说页数，C 说购买时间，D 说评价，均未回答价格。"},
  {"id":"lis-108","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: Would you mind opening the window?","options":[{"key":"A","text":"No, of course not."},{"key":"B","text":"Yes, I opened it."},{"key":"C","text":"The window is new."},{"key":"D","text":"It's a nice room."}],"answer":"A","explanation":"Would you mind doing sth.? 意为“你介意做某事吗”，表示不介意用 No, of course not. / Not at all.；若介意则用 Sorry, but...。"},
  {"id":"lis-109","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: What does your father do?","options":[{"key":"A","text":"He is doing his homework."},{"key":"B","text":"He is a bus driver."},{"key":"C","text":"He is fine, thank you."},{"key":"D","text":"He is at home now."}],"answer":"B","explanation":"What does sb. do? 是询问职业的固定句型，应答应给出职业。D 回答的是地点，C 回答的是身体状况。"},
  {"id":"lis-110","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: How often do you go to the gym?","options":[{"key":"A","text":"Twice a week."},{"key":"B","text":"For two hours."},{"key":"C","text":"By bus."},{"key":"D","text":"With my friends."}],"answer":"A","explanation":"How often 询问频率，应答用 once a week、twice a month 等。B 回答时长，C 回答方式，D 回答和谁一起。"},
  {"id":"lis-111","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: Hello, may I speak to Mr. Wang, please?","options":[{"key":"A","text":"Hold on, please. I'll get him."},{"key":"B","text":"Yes, you may go now."},{"key":"C","text":"He speaks English well."},{"key":"D","text":"This is a telephone."}],"answer":"A","explanation":"打电话要求找某人时，应答常用 Hold on, please.（请稍等）或 This is he speaking.（我就是）。"},
  {"id":"lis-112","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: What's the weather like in Beijing in autumn?","options":[{"key":"A","text":"It's cool and dry."},{"key":"B","text":"It's a big city."},{"key":"C","text":"I went there by plane."},{"key":"D","text":"Autumn is my favourite season."}],"answer":"A","explanation":"What's the weather like? 询问天气状况，应答应描述天气（凉爽干燥）。D 虽提到季节但并未描述天气。"},
  {"id":"lis-113","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: Why didn't you come to the party last night?","options":[{"key":"A","text":"Because I had to work overtime."},{"key":"B","text":"Yes, I like parties."},{"key":"C","text":"The party was at eight."},{"key":"D","text":"I came here by taxi."}],"answer":"A","explanation":"Why 询问原因，应答须用 because 说明理由。B 用 Yes 回答 wh- 问句属于典型错误。"},
  {"id":"lis-114","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: Could you give me a hand with these boxes?","options":[{"key":"A","text":"Sure, no problem."},{"key":"B","text":"Yes, my hands are clean."},{"key":"C","text":"The boxes are heavy."},{"key":"D","text":"I have two hands."}],"answer":"A","explanation":"give sb. a hand 是习语，意为“帮某人一把”，并非字面的“给手”。应答表示愿意帮忙用 Sure, no problem.。"},
  {"id":"lis-115","type":"listening","kind":"single","score":1,"bank":"短对话·应答","stem":"听录音，选择对下面问题的恰当回答。\nquestion: Excuse me, is this seat taken?","options":[{"key":"A","text":"No, it's free. Please sit down."},{"key":"B","text":"Yes, I took a seat."},{"key":"C","text":"The seat is made of wood."},{"key":"D","text":"I'll take the bus."}],"answer":"A","explanation":"Is this seat taken? 意为“这个座位有人吗”，应答应说明是否可坐。此处 taken 表示“被占用”。"},
  {"id":"lis-116","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nM: What time does the film begin?\nW: At half past seven, and we should arrive ten minutes earlier.\nquestion: When will they arrive at the cinema?","options":[{"key":"A","text":"At 7:00."},{"key":"B","text":"At 7:20."},{"key":"C","text":"At 7:30."},{"key":"D","text":"At 7:40."}],"answer":"B","explanation":"电影 7:30 开始，应提前 10 分钟到，即 7:20。此题需在听懂时间的基础上做简单计算。"},
  {"id":"lis-117","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nW: Where is the nearest bank?\nM: Go along this street and turn left at the second crossing. It's next to a post office.\nquestion: Where is the bank?","options":[{"key":"A","text":"Next to a post office."},{"key":"B","text":"Opposite a hospital."},{"key":"C","text":"Behind a school."},{"key":"D","text":"In front of a hotel."}],"answer":"A","explanation":"男士说银行“It's next to a post office”，即紧挨着邮局。"},
  {"id":"lis-118","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nM: How much are these two books?\nW: One is 25 yuan and the other is 15 yuan.\nquestion: How much should the man pay in total?","options":[{"key":"A","text":"15 yuan."},{"key":"B","text":"25 yuan."},{"key":"C","text":"40 yuan."},{"key":"D","text":"50 yuan."}],"answer":"C","explanation":"两本书分别为 25 元和 15 元，合计 40 元。此题考查简单的加法计算。"},
  {"id":"lis-119","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nW: You look tired, Jack. What's wrong?\nM: I stayed up late last night to finish my report.\nquestion: Why does Jack look tired?","options":[{"key":"A","text":"He was ill."},{"key":"B","text":"He stayed up late."},{"key":"C","text":"He did too much exercise."},{"key":"D","text":"He got up too early."}],"answer":"B","explanation":"男士说“I stayed up late last night to finish my report”，因熬夜写报告而疲惫。stay up late 意为“熬夜”。"},
  {"id":"lis-120","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nM: Hello, this is David speaking. May I speak to Alice?\nW: I'm sorry, she is not in. Can I take a message?\nquestion: What does the woman offer to do?","options":[{"key":"A","text":"Take a message."},{"key":"B","text":"Call back later."},{"key":"C","text":"Give him Alice's number."},{"key":"D","text":"Ask Alice to wait."}],"answer":"A","explanation":"女士说“Can I take a message?”，主动提出帮忙留言。take a message 意为“捎口信、记留言”。"},
  {"id":"lis-121","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nW: What's your plan for the summer holiday?\nM: I'm going to visit my grandparents in the countryside.\nquestion: What is the man going to do?","options":[{"key":"A","text":"Find a part-time job."},{"key":"B","text":"Visit his grandparents."},{"key":"C","text":"Take a trip abroad."},{"key":"D","text":"Stay at school."}],"answer":"B","explanation":"男士说“I'm going to visit my grandparents in the countryside”，计划去乡下看望祖父母。"},
  {"id":"lis-122","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nM: Can I help you, madam?\nW: Yes, I'd like to buy a pair of shoes for my son. Size 38, please.\nquestion: What does the woman want to buy?","options":[{"key":"A","text":"A pair of shoes."},{"key":"B","text":"A school bag."},{"key":"C","text":"A T-shirt."},{"key":"D","text":"A pair of glasses."}],"answer":"A","explanation":"女士说“I'd like to buy a pair of shoes for my son”，想给儿子买一双 38 码的鞋。"},
  {"id":"lis-123","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nW: Where do you work, Mr. Li?\nM: I work in a bank, but I worked in a hotel three years ago.\nquestion: Where does Mr. Li work now?","options":[{"key":"A","text":"In a hotel."},{"key":"B","text":"In a bank."},{"key":"C","text":"In a school."},{"key":"D","text":"In a hospital."}],"answer":"B","explanation":"男士说“I work in a bank”，现在在银行工作；三年前在酒店工作，为干扰信息。注意时态的区别。"},
  {"id":"lis-124","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nM: The train leaves at 8:15. We have only twenty minutes left.\nW: Then we'd better take a taxi.\nquestion: How will they probably go to the station?","options":[{"key":"A","text":"By bus."},{"key":"B","text":"By bike."},{"key":"C","text":"By taxi."},{"key":"D","text":"On foot."}],"answer":"C","explanation":"女士说“we'd better take a taxi”，因为时间紧张，他们很可能打车去车站。"},
  {"id":"lis-125","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nW: Have you finished the report, Tom?\nM: Not yet. I'll finish it by Friday.\nquestion: When will Tom finish the report?","options":[{"key":"A","text":"By Wednesday."},{"key":"B","text":"By Thursday."},{"key":"C","text":"By Friday."},{"key":"D","text":"By Sunday."}],"answer":"C","explanation":"男士说“I'll finish it by Friday”，将在周五前完成报告。by Friday 意为“在周五之前”。"},
  {"id":"lis-126","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nM: Excuse me, is there a bookstore near here?\nW: Yes, there is one just across the street, next to the coffee shop.\nquestion: Where is the bookstore?","options":[{"key":"A","text":"Across the street."},{"key":"B","text":"Inside the coffee shop."},{"key":"C","text":"Behind the man's house."},{"key":"D","text":"On the second floor."}],"answer":"A","explanation":"女士说书店“just across the street, next to the coffee shop”，就在街对面、咖啡店旁边。"},
  {"id":"lis-127","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nW: I hear you've moved to a new flat.\nM: Yes, it's bigger and quieter than the old one, and the rent is almost the same.\nquestion: What does the man think of his new flat?","options":[{"key":"A","text":"It is smaller but cheaper."},{"key":"B","text":"It is bigger and quieter."},{"key":"C","text":"It is far from his office."},{"key":"D","text":"It is much more expensive."}],"answer":"B","explanation":"男士说新公寓“bigger and quieter than the old one, and the rent is almost the same”，更大更安静，租金差不多。"},
  {"id":"lis-128","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nM: Would you like tea or coffee?\nW: Neither, thanks. I'd prefer some hot water.\nquestion: What would the woman like to drink?","options":[{"key":"A","text":"Tea."},{"key":"B","text":"Coffee."},{"key":"C","text":"Hot water."},{"key":"D","text":"Orange juice."}],"answer":"C","explanation":"女士用 Neither 否定了茶和咖啡，并说“I'd prefer some hot water”，想喝热水。neither 意为“两者都不”。"},
  {"id":"lis-129","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nW: How was your interview yesterday?\nM: Quite good. They said they would call me in three days if I got the job.\nquestion: What will happen in three days?","options":[{"key":"A","text":"The man will have another interview."},{"key":"B","text":"The company may call the man."},{"key":"C","text":"The man will start working."},{"key":"D","text":"The woman will call the company."}],"answer":"B","explanation":"男士说“They said they would call me in three days if I got the job”，三天后公司可能会打电话通知结果。"},
  {"id":"lis-130","type":"listening","kind":"single","score":1,"bank":"短对话·理解","stem":"听对话，回答问题。\nM: The weather report says it will rain tomorrow.\nW: Really? Then we have to put off our picnic.\nquestion: What will they do tomorrow?","options":[{"key":"A","text":"Go on a picnic."},{"key":"B","text":"Put off the picnic."},{"key":"C","text":"Stay at the office."},{"key":"D","text":"Watch a film."}],"answer":"B","explanation":"女士说“Then we have to put off our picnic”，因明天有雨，他们将推迟野餐。put off 意为“推迟”。"}
];
